-- Final reviewed directory schema and current development data. Public routes remain drafts.
BEGIN;
SET LOCAL search_path = pg_catalog, public;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';


-- Reuse an equivalent final table; never replay the retired schema experiments.
DO $table_guard$
BEGIN
 IF to_regclass('public.platform_fee_sections') IS NULL THEN
  CREATE TABLE public."platform_fee_sections" (
 "id" text NOT NULL,
 "name" text NOT NULL,
 "sort_order" integer NOT NULL,
 "fields" jsonb NOT NULL,
 "icon" text DEFAULT 'Smartphone'::text NOT NULL,
 "group_name" text DEFAULT 'Apps and software'::text NOT NULL,
 "intro" text DEFAULT ''::text NOT NULL,
 "meta_title" text DEFAULT ''::text NOT NULL,
 "meta_description" text DEFAULT ''::text NOT NULL,
 "related_sections" jsonb DEFAULT '[]'::jsonb NOT NULL,
