 CONSTRAINT "platform_fee_sections_id_check" CHECK (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text),
 CONSTRAINT "platform_fee_sections_name_check" CHECK (length(btrim(name)) > 0),
 CONSTRAINT "platform_fee_sections_pkey" PRIMARY KEY (id),
 CONSTRAINT "platform_fee_sections_related_sections_check" CHECK (jsonb_typeof(related_sections) = 'array'::text),
 CONSTRAINT "platform_fee_sections_sort_order_check" CHECK (sort_order >= 0)
);
  ALTER TABLE public."platform_fee_sections" ENABLE ROW LEVEL SECURITY;


 END IF;
 IF (SELECT coalesce(jsonb_agg(jsonb_build_object(
 'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,
 'identity',a.attidentity,'generated',a.attgenerated,'default_value',pg_get_expr(d.adbin,d.adrelid),
 'collation',CASE WHEN a.attcollation<>t.typcollation THEN quote_ident(n.nspname)||'.'||quote_ident(co.collname) END)
 ORDER BY a.attnum),'[]'::jsonb)
 FROM pg_attribute a JOIN pg_type t ON t.oid=a.atttypid
 LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
 LEFT JOIN pg_collation co ON co.oid=a.attcollation LEFT JOIN pg_namespace n ON n.oid=co.collnamespace
 WHERE a.attrelid='public.platform_fee_sections'::regclass AND a.attnum>0 AND NOT a.attisdropped) IS DISTINCT FROM $expected_columns$[{"name":"id","type":"text","not_null":true,"identity":"","generated":"","default_value":null,"collation":null},{"name":"name","type":"text","not_null":true,"identity":"","generated":"","default_value":null,"collation":null},{"name":"sort_order","type":"integer","not_null":true,"identity":"","generated":"","default_value":null,"collation":null},{"name":"fields","type":"jsonb","not_null":true,"identity":"","generated":"","default_value":null,"collation":null},{"name":"icon","type":"text","not_null":true,"identity":"","generated":"","default_value":"'Smartphone'::text","collation":null},{"name":"group_name","type":"text","not_null":true,"identity":"","generated":"","default_value":"'Apps and software'::text","collation":null},{"name":"intro","type":"text","not_null":true,"identity":"","generated":"","default_value":"''::text","collation":null},{"name":"meta_title","type":"text","not_null":true,"identity":"","generated":"","default_value":"''::text","collation":null},{"name":"meta_description","type":"text","not_null":true,"identity":"","generated":"","default_value":"''::text","collation":null},{"name":"related_sections","type":"jsonb","not_null":true,"identity":"","generated":"","default_value":"'[]'::jsonb","collation":null}]$expected_columns$::jsonb THEN
  RAISE EXCEPTION 'public.platform_fee_sections: column schema differs from the reviewed final schema';
 END IF;
 IF (SELECT coalesce(jsonb_agg(jsonb_build_object('name',conname,'type',contype,'definition',pg_get_constraintdef(oid,true),'condeferrable',condeferrable,'condeferred',condeferred,'convalidated',convalidated) ORDER BY conname),'[]'::jsonb) FROM pg_constraint WHERE conrelid='public.platform_fee_sections'::regclass) IS DISTINCT FROM $expected_constraints$[{"name":"platform_fee_sections_fields_check","type":"c","definition":"CHECK (jsonb_typeof(fields) = 'array'::text AND jsonb_array_length(fields) >= 4 AND jsonb_array_length(fields) <= 5)","condeferrable":false,"condeferred":false,"convalidated":true},{"name":"platform_fee_sections_id_check","type":"c","definition":"CHECK (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text)","condeferrable":false,"condeferred":false,"convalidated":true},{"name":"platform_fee_sections_name_check","type":"c","definition":"CHECK (length(btrim(name)) > 0)","condeferrable":false,"condeferred":false,"convalidated":true},{"name":"platform_fee_sections_pkey","type":"p","definition":"PRIMARY KEY (id)","condeferrable":false,"condeferred":false,"convalidated":true},{"name":"platform_fee_sections_related_sections_check","type":"c","definition":"CHECK (jsonb_typeof(related_sections) = 'array'::text)","condeferrable":false,"condeferred":false,"convalidated":true},{"name":"platform_fee_sections_sort_order_check","type":"c","definition":"CHECK (sort_order >= 0)","condeferrable":false,"condeferred":false,"convalidated":true}]$expected_constraints$::jsonb THEN
  RAISE EXCEPTION 'public.platform_fee_sections: constraints differ from the reviewed final schema';
