 END IF;
 IF NOT (SELECT relrowsecurity AND NOT relforcerowsecurity FROM pg_class WHERE oid='public.platform_fee_sections'::regclass) THEN
  RAISE EXCEPTION 'public.platform_fee_sections: unexpected row security configuration';
 END IF;
END;
$table_guard$;

-- Draft data is served by the server; the browser Data API cannot read or write it.
REVOKE ALL ON TABLE public."platform_fee_sections" FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public."platform_fee_sections" TO service_role;
DO $policy_guard$
DECLARE policy_row record;
BEGIN
 FOR policy_row IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename='platform_fee_sections' LOOP
  EXECUTE format('DROP POLICY %I ON public.%I',policy_row.policyname,'platform_fee_sections');
 END LOOP;
END;
$policy_guard$;

