sources":[{"url": "https://www.humblebundle.com/store", "label": "Humble Store"}, {"url": "https://humblebundleorg2022.my.site.com/SubmissionFormPortal/s/game-submission-form", "label": "Game submission form"}],"checked_at":"2026-09-30","comparison_basis":"Curated PC-store sales; current partner rates and payout terms are not public.","fee_percent":null,"fee_basis":null,"sort_order":4,"card":{"tag": "Curated PC games", "note": "Humble does not publish its current seller terms.", "take": {"label": "Partner share", "value": "Share not disclosed", "percent": null, "fact_key": "fact-1"}, "lines": [{"label": "Start", "value": "Not published", "fact_key": "fact-2"}, {"label": "Payouts", "value": "Not published", "fact_key": "fact-3"}, {"label": "Access", "value": "Submission form", "fact_key": "fact-4"}], "owner": "Humble", "groups": []}}, {"id":"pc-games--itch-io","section_id":"pc-games","name":"itch.io","summary":"Sell indie games with a revenue share you set.","website_url":"https://itch.io/developers","icon_path":"/platform-fees/icons/itch-io.ico","facts":[{"key": "fact-1", "state": "verified", "value": "Seller sets itch.io’s revenue share from 0% to 100%; the default is 10%", "checked_at": "2026-09-30", "source_url": "https://itch.io/docs/creators/payments"}, {"key": "fact-2", "state": "verified", "value": "Free account; itch.io Payouts requires tax identity and a one-time $3 verification fee", "checked_at": "2026-09-30", "source_url": "https://itch.io/docs/creators/payments"}, {"key": "fact-3", "state": "variable", "value": "PayPal/Stripe typically charge 2.9% + $0.30; currency and payout fees vary", "checked_at": "2026-09-30", "source_url": "https://itch.io/docs/creators/payments"}, {"key": "fact-4", "state": "verified", "value": "Marketplace; Direct makes seller MoR, while itch.io Payouts makes itch.io MoR", "checked_at": "2026-09-30", "source_url": "https://itch.io/docs/creators/payments"}],"sources":[{"url": "https://itch.io/docs/creators/payments", "label": "Revenue share and payouts"}, {"url": "https://itch.io/docs/creators/getting-started", "label": "Creator account setup"}],"checked_at":"2026-09-30","comparison_basis":"Seller-configured share; default is 10%. Processor fees and tax handling depend on direct payments versus itch.io Payouts.","fee_percent":null,"fee_basis":null,"sort_order":3,"card":{"tag": "Indie games", "note": "You set itch.io’s share yourself. PayPal or Stripe fees are extra.", "take": {"label": "Default share", "value": "10%", "percent": 10, "fact_key": "fact-1"}, "lines": [{"label": "Start", "value": "Free", "fact_key": "fact-2"}, {"label": "Card fees", "value": "About 2.9% + 30¢", "fact_key": "fact-3"}, {"label": "Payouts setup", "value": "$3 once", "fact_key": "fact-2"}], "owner": "itch.io", "groups": [{"label": "itch.io share", "rates": [{"label": "Default share", "value": "10%", "percent": 10, "fact_key": "fact-1"}, {"label": "Any share you set", "value": "0–100%", "percent": null, "fact_key": "fact-1"}]}], "second": {"label": "Any share you set", "value": "0–100%", "percent": null, "fact_key": "fact-1"}}}, {"id":"pc-games--steam","section_id":"pc-games","name":"Steam","summary":"Publish PC games through Steamworks.","website_url":"https://partner.steamgames.com/","icon_path":"/platform-fees/icons/partner-steamgames-com.ico","facts":[{"key": "fact-1", "state": "verified", "value": "30% first $10M; 25% from $10M to $50M; 20% above $50M per game", "checked_at": "2026-09-30", "source_url": "https://steamcommunity.com/groups/steamworks/announcements/detail/1697191267930157838"}, {"key": "fact-2", "state": "verified", "value": "US$100 per app; recouped after US$1,000 adjusted gross revenue", "checked_at": "2026-09-30", "source_url": "https://partner.steamgames.com/doc/gettingstarted/appfee"}, {"key": "fact-3", "state": "not_public", "value": "No separate seller processing rate is listed. Monthly payout is USD by US ACH or international SWIFT; Valve adds no wire fee, but banks may charge. A US$100 minimum payout may apply.", "checked_at": "2026-09-30", "source_url": "https://partner.steamgames.com/doc/finance/payments_salesreporting/faq"}, {"key": "fact-4", "state": "verified", "value": "Valve reviews the store page and game build before release.", "checked_at": "2026-09-30", "source_url": "https://partner.steamgames.com/doc/store/review_process"}],"sources":[{"url": "https://steamcommunity.com/groups/steamworks/announcements/detail/1697191267930157838", "label": "Revenue share"}, {"url": "https://partner.steamgames.com/doc/gettingstarted/appfee", "label": "Steam Direct fee"}, {"url": "https://partner.steamgames.com/doc/finance/payments_salesreporting/faq", "label": "Payouts and bank fees"}, {"url": "https://partner.steamgames.com/doc/store/review_process", "label": "Store and build review"}, {"url": "https://partner.steamgames.com/doc/gettingstarted/onboarding", "label": "Steamworks onboarding"}],"checked_at":"2026-09-30","comparison_basis":"Tiered worldwide share per game; payout is monthly in USD.","fee_percent":30,"fee_basis":"30% on the first $10M per game, then 25% to $50M and 20% above.","sort_order":0,"card":{"tag": "PC games", "note": "Rates count each game’s lifetime sales. Valve reviews the store page and build before release.", "take": {"label": "First $10M", "value": "30%", "percent": 30, "fact_key": "fact-1"}, "lines": [{"label": "Start", "value": "$100 per game", "fact_key": "fact-2"}, {"label": "Fee back", "value": "After $1,000 in sales", "fact_key": "fact-2"}, {"label": "Payouts", "value": "Monthly, $100 minimum", "fact_key": "fact-3"}], "owner": "Valve", "groups": [{"label": "Per game, lifetime sales", "rates": [{"label": "First $10M", "value": "30%", "percent": 30, "fact_key": "fact-1"}, {"label": "$10M to $50M", "value": "25%", "percent": 25, "fact_key": "fact-1"}, {"label": "Above $50M", "value": "20%", "percent": 20, "fact_key": "fact-1"}]}], "second": {"label": "$10M to $50M", "value": "25%", "percent": 25, "fact_key": "fact-1"}}}, {"id":"photos-and-stock-images--123rf","section_id":"photos-and-stock-images","name":"123RF","summary":"Stock photos and other creative assets licensed through a contributor program.","website_url":"https://www.123rf.com/contributor/","icon_path":"/platform-fees/icons/www-123rf-com.png","facts":[{"key": "fact-1", "state": "verified", "value": "Stock photos, vectors, illustrations, video and audio are licensed through credit and subscription downloads.", "checked_at": "2026-09-30", "source_url": "https://www.123rf.com/submit/agreement.php"}, {"key": "fact-2", "state": "verified", "value": "Credit downloads pay 30%, 40%, 50%, 52%, 54%, 56%, 58% or 60% at levels 1–8, based on prior 12-month downloads. Subscription downloads pay $0.216, $0.288, $0.360, $0.374, $0.389, $0.403, $0.418 or $0.432 by level; earnings round to cents.", "checked_at": "2026-09-30", "source_url": "https://www.123rf.com/contrib_structure/"}, {"key": "fact-3", "state": "not_public", "value": "The public contributor agreement does not state an account or upload fee; it permits deduction of payment processing or bank transaction charges when incurred.", "checked_at": "2026-09-30", "source_url": "https://www.123rf.com/submit/agreement.php"}, {"key": "fact-4", "state": "verified", "value": "The contributor grants 123RF a worldwide, non-exclusive distribution and licensing right.", "checked_at": "2026-09-30", "source_url": "https://www.123rf.com/submit/agreement.php"}, {"key": "fact-5", "state": "verified", "value": "Automatic payment on or after the 15th after threshold: $50 via PayPal or Payoneer, $100 via Skrill. A tax form is required; processing or bank charges may be deducted.", "checked_at": "2026-09-30", "source_url": "https://www.123rf.com/submit/agreement.php"}],"sources":[{"url": "https://www.123rf.com/contrib_structure/", "label": "Commission by level"}, {"url": "https://www.123rf.com/submit/agreement.php", "label": "Contributor agreement"}, {"url": "https://www.123rf.com/contributors/", "label": "Program and payouts"}],"checked_at":"2026-09-30","comparison_basis":"Credit-pack rates use the previous 12 months of downloads; subscriptions pay fixed per-download amounts.","fee_percent":null,"fee_basis":null,"sort_order":6,"card":{"tag": "Stock photos and video", "note": "Your level is based on downloads over the past 12 months.", "take": {"label": "Credit downloads", "value": "40–70%", "percent": null, "fact_key": "fact-2"}, "lines": [{"label": "Start", "value": "No fee stated", "fact_key": "fact-3"}, {"label": "Exclusive", "value": "No", "fact_key": "fact-4"}, {"label": "Minimum payout", "value": "$50", "fact_key": "fact-5"}], "owner": "123RF", "groups": [{"label": "Credit downloads, by level", "rates": [{"note": "You keep 30%", "label": "Level 1", "value": "70%", "percent": 70, "fact_key": "fact-2"}, {"note": "You keep 60%", "label": "Level 8", "value": "40%", "percent": 40, "fact_key": "fact-2"}]}, {"label": "Subscriptions", "rates": [{"label": "Per download", "value": "$0.22–0.43", "percent": null, "fact_key": "fact-2"}]}]}}, {"id":"photos-and-stock-images--adobe-stock","section_id":"photos-and-stock-images","name":"Adobe Stock","summary":"License stock content to Adobe customers.","website_url":"https://contributor.stock.adobe.com/","icon_path":"/platform-fees/icons/contributor-stock-adobe-com.png","facts":[{"key": "fact-1", "state": "verified", "value": "Standard stock licenses cover photos, vectors, illustrations and video under subscriptions, credit packs and on-demand plans.", "checked_at": "2026-09-30", "source_url": "https://helpx.adobe.com/stock/contributor/payments-earnings/royalties-pricing/royalty-rates-assets.html"}, {"key": "fact-2", "state": "verified", "value": "Standard rates are 33% for photos, vectors and illustrations and 35% for video, applied to net licensed price. Some non-standard plans use flat rates. Large subscriptions guarantee $0.33–$0.38 per standard still asset by contributor lifetime-license tier.", "checked_at": "2026-09-30", "source_url": "https://helpx.adobe.com/stock/contributor/payments-earnings/royalties-pricing/royalty-rates-assets.html"}, {"key": "fact-3", "state": "verified", "value": "Adobe describes contributor setup as having no upfront or subscription cost.", "checked_at": "2026-09-30", "source_url": "https://helpx.adobe.com/stock/contributor/get-started/become-contributor/contributor-overview.html"}, {"key": "fact-4", "state": "variable", "value": "Standard uploads and accepted Free Collection works are non-exclusive. Supplemental Work may be exclusive only when the request expressly requires it.", "checked_at": "2026-09-30", "source_url": "https://helpx.adobe.com/stock/contributor/get-started/become-contributor/benefits-contributing-content.html"}, {"key": "fact-5", "state": "verified", "value": "Payout requests require at least $25 and 45 days since the first sale. PayPal, Payoneer and Skrill are offered, subject to regional eligibility and tax requirements.", "checked_at": "2026-09-30", "source_url": "https://helpx.adobe.com/stock/contributor/payments-earnings/payment-taxes/payment-requirements.html"}],"sources":[{"url": "https://helpx.adobe.com/stock/contributor/payments-earnings/royalties-pricing/royalty-rates-assets.html", "label": "Royalty rates"}, {"url": "https://helpx.adobe.com/stock/contributor/get-started/become-contributor/contributor-overview.html", "label": "Account and submission"}, {"url": "https://helpx.adobe.com/stock/contributor/get-started/become-contributor/benefits-contributing-content.html", "label": "Contributor rights"}, {"url": "https://helpx.adobe.com/stock/contributor/additional-earning-opportunities/free-collection-faq.html", "label": "Free Collection terms"}, {"url": "https://helpx.adobe.com/stock/contributor/payments-earnings/royalties-pricing/pricing-payment-guidelines.html", "label": "Supplemental Work terms"}, {"url": "https://helpx.adobe.com/stock/contributor/payments-earnings/payment-taxes/payment-requirements.html", "label": "Payouts"}],"checked_at":"2026-09-30","comparison_basis":"Standard royalties use the net licensed price; special plans may use a flat rate.","fee_percent":null,"fee_basis":null,"sort_order":0,"card":{"tag": "Stock photos and video", "note": "Large subscriptions pay a flat $0.33 to $0.38 per image instead.", "take": {"label": "Photos and vectors", "value": "67%", "percent": 67, "fact_key": "fact-2"}, "lines": [{"label": "Start", "value": "Free", "fact_key": "fact-3"}, {"label": "Exclusive", "value": "No", "fact_key": "fact-4"}, {"label": "Minimum payout", "value": "$25", "fact_key": "fact-5"}], "owner": "Adobe", "groups": [{"label": "Standard licenses", "rates": [{"note": "You keep 33%", "label": "Photos and vectors", "value": "67%", "percent": 67, "fact_key": "fact-2"}, {"note": "You keep 35%", "label": "Video", "value": "65%", "percent": 65, "fact_key": "fact-2"}]}], "second": {"label": "Video", "value": "65%", "percent": 65, "fact_key": "fact-2"}}}, {"id":"photos-and-stock-images--alamy","section_id":"photos-and-stock-images","name":"Alamy","summary":"License photos, vectors, video and 360° images under annual commission tiers.","website_url":"https://www.alamy.com/contributor/","icon_path":"/platform-fees/icons/www-alamy-com.png","facts":[{"key": "fact-1", "state": "verified", "value": "Stock licensing for photos, vectors, video and 360° images.", "checked_at": "2026-09-30", "source_url": "https://www.alamy.com/terms/contributor/"}, {"key": "fact-2", "state": "verified", "value": "2026 tiers: Bronze 15% below $250; Silver 20% at $250–$3,000; Gold 40% above $3,000 to $25,000; Platinum 50% for eligible Alamy-exclusive content at $25,000+. Tiers are based on annual licence fees net of refunds. Eligible students receive 100% of direct sales for two years.", "checked_at": "2026-09-30", "source_url": "https://www.alamy.com/terms/contributor/"}, {"key": "fact-3", "state": "verified", "value": "Alamy offers a free contributor account.", "checked_at": "2026-09-30", "source_url": "https://www.alamy.com/terms/contributor/"}, {"key": "fact-4", "state": "verified", "value": "Standard supply is non-exclusive. Contributors may mark eligible content exclusive; exclusivity only affects the Platinum commission tier.", "checked_at": "2026-09-30", "source_url": "https://www.alamy.com/terms/contributor/"}, {"key": "fact-5", "state": "verified", "value": "Monthly payment once cleared funds exceed $75; USD, GBP or EUR by PayPal or bank transfer. Processing starts the first working day and may take up to nine working days.", "checked_at": "2026-09-30", "source_url": "https://www.alamy.com/help/contributor-sales-and-payment/"}],"sources":[{"url": "https://www.alamy.com/terms/contributor/", "label": "Contributor contract"}, {"url": "https://www.alamy.com/help/contributor-contract/", "label": "Commission tiers"}, {"url": "https://www.alamy.com/help/contributor-sales-and-payment/", "label": "Payouts"}, {"url": "https://www.alamy.com/contributor/100-percent-students/", "label": "Student program"}],"checked_at":"2026-09-30","comparison_basis":"Annual revenue tiers; payment can be made in USD, GBP or EUR.","fee_percent":null,"fee_basis":null,"sort_order":3,"card":{"tag": "Stock photos and video", "note": "Your tier depends on the license fees you earned over the year.", "take": {"label": "Bronze, under $250", "value": "85%", "percent": 85, "fact_key": "fact-2"}, "lines": [{"label": "Start", "value": "Free", "fact_key": "fact-3"}, {"label": "Exclusive", "value": "Optional", "fact_key": "fact-4"}, {"label": "Minimum payout", "value": "$75", "fact_key": "fact-5"}], "owner": "Alamy", "groups": [{"label": "By yearly license fees", "rates": [{"note": "You keep 15%", "label": "Bronze, under $250", "value": "85%", "percent": 85, "fact_key": "fact-2"}, {"note": "You keep 20%", "label": "Silver, $250 to $3,000", "value": "80%", "percent": 80, "fact_key": "fact-2"}, {"note": "You keep 40%", "label": "Gold, $3,000 to $25,000", "value": "60%", "percent": 60, "fact_key": "fact-2"}, {"note": "You keep 50%, from $25,000", "label": "Platinum, exclusive", "value": "50%", "percent": 50, "fact_key": "fact-2"}]}, {"label": "Students", "rates": [{"note": "You keep 100%", "label": "Direct sales for 2 years", "value": "0%", "percent": 0, "fact_key": "fact-2"}]}], "second": {"label": "Platinum, exclusive", "value": "50%", "percent": 50, "fact_key": "fact-2"}}}, {"id":"photos-and-stock-images--depositphotos","section_id":"photos-and-stock-images","name":"Depositphotos","summary":"Stock licensing with download-based contributor levels.","website_url":"https://depositphotos.com/seller-price.html","icon_path":"/platform-fees/icons/depositphotos-com.ico","facts":[{"key": "fact-1", "state": "verified", "value": "Contributor licensing covers photos, vectors, video and audio through packs, subscriptions and special revenue-share plans.", "checked_at": "2026-09-30", "source_url": "https://depositphotos.com/seller-price.html"}, {"key": "fact-2", "state": "verified", "value": "Photo/vector packs pay 30%, 32%, 34%, 36% or 38% by level; subscriptions pay $0.25–$0.33 per file. Video packs/subscriptions pay 30–38%; audio packs pay 34–42%. Unlimited music subscriptions allocate 40% of net subscription revenue by download share. Discounts, tax and partner deals can change amounts.", "checked_at": "2026-09-30", "source_url": "https://depositphotos.com/seller-price.html"}, {"key": "fact-3", "state": "verified", "value": "Contributor account registration is free; applicants pass a brief examination with sample files.", "checked_at": "2026-09-30", "source_url": "https://depositphotos.com/seller-price.html"}, {"key": "fact-4", "state": "verified", "value": "Supply agreement grants Depositphotos a perpetual, worldwide, non-exclusive license.", "checked_at": "2026-09-30", "source_url": "https://depositphotos.com/supply-agreement.html"}, {"key": "fact-5", "state": "verified", "value": "Withdraw at $25 or more via PayPal, Payoneer or Skrill; an approved tax form is required.", "checked_at": "2026-09-30", "source_url": "https://depositphotos.com/faq/contributor/article/24412003777426.html"}],"sources":[{"url": "https://depositphotos.com/seller-price.html", "label": "Rates and registration"}, {"url": "https://depositphotos.com/supply-agreement.html", "label": "Supply agreement"}, {"url": "https://depositphotos.com/faq/contributor/article/24412003777426.html", "label": "Payouts"}],"checked_at":"2026-09-30","comparison_basis":"Royalty depends on contributor level, purchase route, file type, discount and partner terms.","fee_percent":null,"fee_basis":null,"sort_order":5,"card":{"tag": "Stock photos and video", "note": "Video pays 30–38% and audio 34–42%, by level.", "take": {"label": "Photo and vector packs", "value": "62–70%", "percent": null, "fact_key": "fact-2"}, "lines": [{"label": "Start", "value": "Free, short exam", "fact_key": "fact-3"}, {"label": "Exclusive", "value": "No", "fact_key": "fact-4"}, {"label": "Minimum payout", "value": "$25", "fact_key": "fact-5"}], "owner": "Depositphotos", "groups": [{"label": "Packs, by level", "rates": [{"note": "You keep 30%", "label": "Green level", "value": "70%", "percent": 70, "fact_key": "fact-2"}, {"note": "You keep 38%", "label": "Platinum level", "value": "62%", "percent": 62, "fact_key": "fact-2"}]}, {"label": "Other", "rates": [{"label": "Per subscription image", "value": "$0.25–0.33", "percent": null, "fact_key": "fact-2"}, {"note": "Artists share 40%", "label": "Music subscription pool", "value": "60%", "percent": 60, "fact_key": "fact-2"}]}]}}, {"id":"photos-and-stock-images--dreamstime","section_id":"photos-and-stock-images","name":"Dreamstime","summary":"Stock image licensing with optional exclusivity tiers.","website_url":"https://www.dreamstime.com/sell-stock-photos-images","icon_path":"/platform-fees/icons/www-dreamstime-com.ico","facts":[{"key": "fact-1", "state": "verified", "value": "Stock photos, illustrations, video and audio are licensed through per-sale and subscription plans.", "checked_at": "2026-09-30", "source_url": "https://www.dreamstime.com/sell-stock-photos-images"}, {"key": "fact-2", "state": "verified", "value": "Non-exclusive files earn 25–50% of net sales; exclusive files 27.5–55%; exclusive contributors earn 60%. A $0.20 upload bonus applies to each of the first 100 accepted files; after that, through 10,000 files, it requires downloads per image above 0.1. Subscription royalties can vary by plan.", "checked_at": "2026-09-30", "source_url": "https://www.dreamstime.com/terms"}, {"key": "fact-3", "state": "verified", "value": "Contributor registration and uploads are free.", "checked_at": "2026-09-30", "source_url": "https://www.dreamstime.com/sell-stock-photos-images"}, {"key": "fact-4", "state": "verified", "value": "Optional exclusivity applies to individual files or to the contributor portfolio; full exclusivity earns 60% on represented-file sales.", "checked_at": "2026-09-30", "source_url": "https://www.dreamstime.com/terms"}, {"key": "fact-5", "state": "verified", "value": "Request payment at $100 or more via PayPal, Payoneer, Skrill or check.", "checked_at": "2026-09-30", "source_url": "https://www.dreamstime.com/faqs-detail-2"}],"sources":[{"url": "https://www.dreamstime.com/terms", "label": "Royalty and exclusivity"}, {"url": "https://www.dreamstime.com/sell-stock-photos-images", "label": "Rates and payouts"}, {"url": "https://www.dreamstime.com/faqs-detail-2", "label": "Payout methods"}],"checked_at":"2026-09-30","comparison_basis":"Rates apply to net sale and vary by file level, exclusivity and license plan.","fee_percent":null,"fee_basis":null,"sort_order":4,"card":{"tag": "Stock photos and video", "note": "The first 100 accepted files each earn a 20¢ upload bonus.", "take": {"label": "Non-exclusive files", "value": "50–75%", "percent": null, "fact_key": "fact-2"}, "lines": [{"label": "Start", "value": "Free", "fact_key": "fact-3"}, {"label": "Exclusive", "value": "Optional", "fact_key": "fact-4"}, {"label": "Minimum payout", "value": "$100", "fact_key": "fact-5"}], "owner": "Dreamstime", "groups": [{"label": "Royalty", "rates": [{"note": "You keep 25–50%", "label": "Non-exclusive files", "value": "50–75%", "percent": null, "fact_key": "fact-2"}, {"note": "You keep 27.5–55%", "label": "Exclusive files", "value": "45–72.5%", "percent": null, "fact_key": "fact-2"}, {"note": "You keep 60%", "label": "Exclusive contributors", "value": "40%", "percent": 40, "fact_key": "fact-2"}]}], "second": {"label": "Exclusive contributors", "value": "40%", "percent": 40, "fact_key": "fact-2"}}}, {"id":"photos-and-stock-images--fine-art-america-digital-licensing","section_id":"photos-and-stock-images","name":"Pixels.com (Fine Art America)","summary":"Set your own image-license prices through Fine Art America’s Pixels.com marketplace.","website_url":"https://fineartamerica.com/sellimagelicenses.html","icon_path":"/platform-fees/icons/fineartamerica-com.ico","facts":[{"key": "fact-1", "state": "verified", "value": "Sell royalty-free and rights-managed digital image licenses on Pixels.com.", "checked_at": "2026-09-30", "source_url": "https://fineartamerica.com/sellimagelicenses.html"}, {"key": "fact-2", "state": "verified", "value": "You receive 100% of your asking price. Pixels.com adds a 30% markup for buyers, so the asking price is about 77% of the buyer’s total.", "checked_at": "2026-09-30", "source_url": "https://fineartamerica.com/sellimagelicenses.html"}, {"key": "fact-3", "state": "verified", "value": "A Standard account is free and supports up to 25 images. Optional Premium is $30/year and allows unlimited uploads.", "checked_at": "2026-09-30", "source_url": "https://fineartamerica.com/membershipplans.html"}, {"key": "fact-4", "state": "verified", "value": "No exclusivity is required; images may also be listed on other licensing sites.", "checked_at": "2026-09-30", "source_url": "https://fineartamerica.com/sellimagelicenses.html"}, {"key": "fact-5", "state": "variable", "value": "The license page pays monthly on the 15th for sales before the 15th of the prior month, but gives no method. Fine Art America’s general seller page lists PayPal for all members and checks for US members; license-specific applicability is not stated.", "checked_at": "2026-09-30", "source_url": "https://fineartamerica.com/sellimagelicenses.html"}],"sources":[{"url": "https://fineartamerica.com/sellimagelicenses.html", "label": "Licensing and payouts"}, {"url": "https://fineartamerica.com/tour/sell-digital-downloads", "label": "Pricing explanation"}, {"url": "https://fineartamerica.com/membershipplans.html", "label": "Membership prices"}, {"url": "https://fineartamerica.com/openanaccountinstaprints.html", "label": "Seller payments"}],"checked_at":"2026-09-30","comparison_basis":"Seller sets a license price; 30% buyer markup; USD and local currencies may be displayed.","fee_percent":null,"fee_basis":null,"sort_order":14,"card":{"tag": "Image licensing", "note": "Buyers pay 30% more than your price, so you get about 77% of what they pay.", "take": {"label": "Added to your price", "value": "30%", "percent": null, "fact_key": "fact-2"}, "lines": [{"label": "Start", "value": "Free, 25 images", "fact_key": "fact-3"}, {"label": "Premium", "value": "$30 a year", "fact_key": "fact-3"}, {"label": "Exclusive", "value": "No", "fact_key": "fact-4"}], "owner": "Pixels.com", "groups": [{"label": "Pixels.com", "rates": [{"note": "You get 100% of your asking price", "label": "Added to your price", "value": "30%", "percent": null, "fact_key": "fact-2"}]}]}}, {"id":"photos-and-stock-images--istock-and-getty-images","section_id":"photos-and-stock-images","name":"iStock and Getty Images","summary":"License photos and illustrations through iStock and Getty Images.","website_url":"https://www.gettyimages.com/workwithus","icon_path":"/platform-fees/icons/www-gettyimages-com.ico","facts":[{"key": "fact-1", "state": "verified", "value": "Creators earn royalties when customers license accepted photos, videos or illustrations.", "checked_at": "2026-09-30", "source_url": "https://www.istockphoto.com/uk/workwithus"}, {"key": "fact-2", "state": "verified", "value": "The public contributor page states 15–45% per licensed file, depending on the contributor agreement.", "checked_at": "2026-09-30", "source_url": "https://www.istockphoto.com/uk/workwithus"}, {"key": "fact-3", "state": "not_public", "value": "The public application page requires six samples but does not state a contributor account or submission fee.", "checked_at": "2026-09-30", "source_url": "https://www.istockphoto.com/uk/workwithus"}, {"key": "fact-4", "state": "verified", "value": "Applicants start with a non-exclusive agreement; they may later apply for exclusive status by content type for higher rates.", "checked_at": "2026-09-30", "source_url": "https://www.istockphoto.com/uk/workwithus"}, {"key": "fact-5", "state": "not_public", "value": "Royalties are paid in USD through PayPal or Payoneer. The public contributor page does not state a minimum balance or payment schedule.", "checked_at": "2026-09-30", "source_url": "https://www.istockphoto.com/uk/workwithus"}],"sources":[{"url": "https://www.istockphoto.com/uk/workwithus", "label": "Contributor terms"}],"checked_at":"2026-09-30","comparison_basis":"Creator rate depends on agreement; payout is in USD and customer license prices vary by content and use.","fee_percent":null,"fee_basis":null,"sort_order":2,"card":{"tag": "Stock photos and video", "note": "Exclusive contributors earn higher rates.", "take": {"label": "By agreement", "value": "55–85%", "percent": null, "fact_key": "fact-2"}, "lines": [{"label": "Start", "value": "Six samples", "fact_key": "fact-3"}, {"label": "Exclusive", "value": "Optional", "fact_key": "fact-4"}, {"label": "Payouts", "value": "PayPal or Payoneer", "fact_key": "fact-5"}], "owner": "Getty Images", "groups": [{"label": "Royalty", "rates": [{"note": "You keep 15–45%", "label": "By agreement", "value": "55–85%", "percent": null, "fact_key": "fact-2"}]}]}}, {"id":"photos-and-stock-images--photoshelter","section_id":"photos-and-stock-images","name":"PhotoShelter","summary":"Sell prints and image licenses through a photography website.","website_url":"https://www.photoshelter.com/","icon_path":"/platform-fees/icons/www-photoshelter-com.png","facts":[{"key": "fact-1", "state": "verified", "value": "Sell print products and image licenses directly through your PhotoShelter site.", "checked_at": "2026-09-30", "source_url": "https://go.photoshelter.com/photographers/terms-and-conditions/"}, {"key": "fact-2", "state": "verified", "value": "Print/product orders: 10% Basic, 9% Standard, or 8% Pro on subtotal excluding shipping/tax; processor fees separate. Image-license fee rate is not confirmed in the accessible schedule.", "checked_at": "2026-09-30", "source_url": "https://support.photoshelter.com/hc/en-us/articles/203373140-Self-Fulfilled-Prints-Products"}, {"key": "fact-3", "state": "not_public", "value": "A paid photographer plan is required. Current plan prices are shown during signup; no public photographer rate table was found.", "checked_at": "2026-09-30", "source_url": "https://go.photoshelter.com/photographers/terms-and-conditions/"}, {"key": "fact-4", "state": "verified", "value": "PhotoShelter receives a non-exclusive service license; its terms do not state a seller exclusivity requirement.", "checked_at": "2026-09-30", "source_url": "https://go.photoshelter.com/photographers/terms-and-conditions/"}, {"key": "fact-5", "state": "verified", "value": "Customers pay the photographer through a connected PayPal, Stripe, or Authorize.net account. PhotoShelter bills transaction fees on the next monthly statement.", "checked_at": "2026-09-30", "source_url": "https://go.photoshelter.com/photographers/terms-and-conditions/"}],"sources":[{"url": "https://support.photoshelter.com/hc/en-us/articles/203373140-Self-Fulfilled-Prints-Products", "label": "Fees by plan"}, {"url": "https://go.photoshelter.com/photographers/terms-and-conditions/", "label": "Seller terms"}],"checked_at":"2026-09-30","comparison_basis":"The 10/9/8% schedule applies to self-fulfilled print/product orders; current image-license rate is not confirmed in accessible public sources.","fee_percent":null,"fee_basis":null,"sort_order":9,"card":{"tag": "Photography website", "note": "Processor fees are extra. License sale fees could not be confirmed.", "take": {"label": "Basic, print orders", "value": "10%", "percent": 10, "fact_key": "fact-2"}, "lines": [{"label": "Plan", "value": "Paid, price at signup", "fact_key": "fact-3"}, {"label": "Payments", "value": "PayPal, Stripe, more", "fact_key": "fact-5"}, {"label": "Exclusive", "value": "No", "fact_key": "fact-4"}], "owner": "PhotoShelter", "groups": [{"label": "Print and product orders", "rates": [{"label": "Basic, print orders", "value": "10%", "percent": 10, "fact_key": "fact-2"}, {"label": "Standard", "value": "9%", "percent": 9, "fact_key": "fact-2"}, {"label": "Pro, print orders", "value": "8%", "percent": 8, "fact_key": "fact-2"}]}], "second": {"label": "Pro, print orders", "value": "8%", "percent": 8, "fact_key": "fact-2"}}}, {"id":"photos-and-stock-images--pic-time","section_id":"photos-and-stock-images","name":"Pic-Time","summary":"Client-gallery store fees change by plan and who collects payment.","website_url":"https://www.pic-time.com/","icon_path":"/platform-fees/icons/www-pic-time-com.png","facts":[{"key": "fact-1", "state": "verified", "value": "Sell prints and digital products from client galleries, with lab fulfillment or self-fulfillment on eligible plans.", "checked_at": "2026-09-30", "source_url": "https://onboarding.pic-time.com/pricing"}, {"key": "fact-2", "state": "verified", "value": "For Pic-Time-collected orders, commission applies to order profit only: Client Delivery Suite is 15% Free/Beginner, 8% Professional, 6% Advanced; Art Store is 15% Professional and 8% Advanced. Eligible paid plans can avoid commission by collecting payments themselves; Beginner Suite and Professional Art Store cannot.", "checked_at": "2026-09-30", "source_url": "https://help.pic-time.com/en/articles/7901454-what-are-the-commission-rates-for-various-subscription-plans"}, {"key": "fact-3", "state": "verified", "value": "Free plan available. Pic-Time Art costs $7/$21/$42 per month with annual billing or $8/$25/$50 monthly for Beginner/Professional/Advanced.", "checked_at": "2026-09-30", "source_url": "https://onboarding.pic-time.com/pricing"}, {"key": "fact-4", "state": "verified", "value": "Photographers retain rights to their content and grant a limited service-use license; no exclusive marketplace license is stated.", "checked_at": "2026-09-30", "source_url": "https://www.pic-time.com/legal/terms-of-service"}, {"key": "fact-5", "state": "variable", "value": "Pic-Time-collected profits go to PayPal on the 1st/15th once over $20 and approved 7 days before payout. Self-collected payments go to Stripe, PayPal, Square, or offline; sales tax and payout handling then belong to the photographer.", "checked_at": "2026-09-30", "source_url": "https://help.pic-time.com/en/articles/8895759-why-didn-t-i-receive-my-payout-yet"}],"sources":[{"url": "https://help.pic-time.com/en/articles/7901454-what-are-the-commission-rates-for-various-subscription-plans", "label": "Commission rates"}, {"url": "https://onboarding.pic-time.com/pricing", "label": "Plan pricing"}, {"url": "https://help.pic-time.com/en/articles/7963078-how-do-i-set-up-photographer-collected-payments", "label": "Your own payments"}, {"url": "https://help.pic-time.com/en/articles/8895759-why-didn-t-i-receive-my-payout-yet", "label": "Payouts"}, {"url": "https://www.pic-time.com/legal/terms-of-service", "label": "Content rights"}],"checked_at":"2026-09-30","comparison_basis":"Pic-Time’s default commission is deducted from order profit, not gross sales. Client Delivery Suite and Art Store have separate plan rates; eligible paid plans avoid it when the photographer collects payment directly.","fee_percent":null,"fee_basis":null,"sort_order":12,"card":{"tag": "Photography galleries", "note": "Commission is on order profit. Collecting payments yourself avoids it on most paid plans.", "take": {"label": "Free and Beginner", "value": "15%", "percent": 15, "fact_key": "fact-2"}, "lines": [{"label": "Plans", "value": "Free to $50 a month", "fact_key": "fact-3"}, {"label": "Own payments", "value": "Avoid commission", "fact_key": "fact-2"}, {"label": "Minimum payout", "value": "$20", "fact_key": "fact-5"}], "owner": "Pic-Time", "groups": [{"label": "Client Delivery Suite", "rates": [{"label": "Free and Beginner", "value": "15%", "percent": 15, "fact_key": "fact-2"}, {"label": "Professional", "value": "8%", "percent": 8, "fact_key": "fact-2"}, {"label": "Advanced", "value": "6%", "percent": 6, "fact_key": "fact-2"}]}, {"label": "Art Store", "rates": [{"label": "Professional", "value": "15%", "percent": 15, "fact_key": "fact-2"}, {"label": "Advanced", "value": "8%", "percent": 8, "fact_key": "fact-2"}]}, {"label": "Your own payments", "rates": [{"label": "Eligible paid plans", "value": "0%", "percent": 0, "fact_key": "fact-2"}]}], "second": {"label": "Advanced", "value": "6%", "percent": 6, "fact_key": "fact-2"}}}, {"id":"photos-and-stock-images--picfair","section_id":"photos-and-stock-images","name":"Picfair","summary":"Sell prints and digital downloads from a branded photography store.","website_url":"https://www.picfair.com/","icon_path":"/platform-fees/icons/www-picfair-com.ico","facts":[{"key": "fact-1", "state": "verified", "value": "Lite: 20-image private preview; public sales require Plus.", "checked_at": "2026-09-30", "source_url": "https://support.picfair.com/hc/en-us/articles/4417585339793-How-much-does-it-cost-to-have-a-Picfair-Store"}, {"key": "fact-2", "state": "verified", "value": "Plus stores have no added sales commission; the photographer receives the exact price set for each image.", "checked_at": "2026-09-30", "source_url": "https://support.picfair.com/hc/en-us/articles/4417585339793-How-much-does-it-cost-to-have-a-Picfair-Store"}, {"key": "fact-3", "state": "verified", "value": "Plus prices are localized across 13 currencies and may include live discounts; monthly and annual billing are offered.", "checked_at": "2026-09-30", "source_url": "https://www.picfair.com/plans"}, {"key": "fact-4", "state": "verified", "value": "Picfair receives a non-exclusive image license; the photographer retains copyright.", "checked_at": "2026-09-30", "source_url": "https://www.picfair.com/contributor-agreements"}, {"key": "fact-5", "state": "variable", "value": "Request a cash-out after a sale. PayPal, UK bank transfer, or Wise where PayPal is unavailable; average processing is 14 days, up to one month at peak volume.", "checked_at": "2026-09-30", "source_url": "https://support.picfair.com/hc/en-us/articles/4417631067793-How-do-I-get-paid-for-my-image-sales"}],"sources":[{"url": "https://support.picfair.com/hc/en-us/articles/4417585339793-How-much-does-it-cost-to-have-a-Picfair-Store", "label": "Store costs"}, {"url": "https://www.picfair.com/plans", "label": "Plus pricing"}, {"url": "https://www.picfair.com/contributor-agreements", "label": "Contributor agreement"}, {"url": "https://support.picfair.com/hc/en-us/articles/4417631067793-How-do-I-get-paid-for-my-image-sales", "label": "Payouts"}],"checked_at":"2026-09-30","comparison_basis":"Photographers keep the exact asking price on published Plus stores. Lite is a private preview; paid Plus is required for public sales. Plus prices vary by country.","fee_percent":0,"fee_basis":"Image price on a published Plus store","sort_order":8,"card":{"tag": "Photography store", "note": "Public sales need the paid Plus plan.", "take": {"label": "Plus plan", "value": "0%", "percent": 0, "fact_key": "fact-2"}, "lines": [{"label": "Lite", "value": "Preview only", "fact_key": "fact-1"}, {"label": "Plus", "value": "Paid monthly or yearly", "fact_key": "fact-3"}, {"label": "Payouts", "value": "About 14 days", "fact_key": "fact-5"}], "owner": "Picfair", "groups": [{"label": "Picfair Plus", "rates": [{"note": "You keep your full price", "label": "Plus plan", "value": "0%", "percent": 0, "fact_key": "fact-2"}]}]}}, {"id":"photos-and-stock-images--pixieset","section_id":"photos-and-stock-images","name":"Pixieset","summary":"Sell prints and digital files directly from client galleries.","website_url":"https://pixieset.com/","icon_path":"/platform-fees/icons/pixieset-com.ico","facts":[{"key": "fact-1", "state": "verified", "value": "Store sells prints, digital downloads, and other photo products directly from client galleries.", "checked_at": "2026-09-30", "source_url": "https://help.pixieset.com/hc/en-us/articles/360043195012-Introduction-to-Pixieset-Store"}, {"key": "fact-2", "state": "verified", "value": "Free accounts pay 15% of the order subtotal, leaving 85% before product and processor costs. Paid plans charge 0% commission; lab, tax, shipping, and processor costs still apply.", "checked_at": "2026-09-30", "source_url": "https://help.pixieset.com/hc/en-us/articles/115002975072-How-does-the-0-commission-fee-work"}, {"key": "fact-3", "state": "verified", "value": "Free includes 3 GB. Paid Client Gallery plans start at $8/month billed annually or $10/month; commission is 0% on paid plans.", "checked_at": "2026-09-30", "source_url": "https://pixieset.com/pricing/"}, {"key": "fact-4", "state": "verified", "value": "Pixieset receives a non-exclusive license to host/use content to provide the service.", "checked_at": "2026-09-30", "source_url": "https://pixieset.com/terms/"}, {"key": "fact-5", "state": "variable", "value": "Stripe or PayPal pays the seller directly; payout timing depends on country and provider. Offline payments require an upgraded plan.", "checked_at": "2026-09-30", "source_url": "https://help.pixieset.com/hc/en-us/articles/115003005252-Getting-Paid-for-your-Store-Orders"}],"sources":[{"url": "https://help.pixieset.com/hc/en-us/articles/360043195012-Introduction-to-Pixieset-Store", "label": "Store overview"}, {"url": "https://help.pixieset.com/hc/en-us/articles/115002975072-How-does-the-0-commission-fee-work", "label": "Commission rules"}, {"url": "https://pixieset.com/pricing/", "label": "Plan pricing"}, {"url": "https://help.pixieset.com/hc/en-us/articles/115003005252-Getting-Paid-for-your-Store-Orders", "label": "Payouts"}, {"url": "https://pixieset.com/terms/", "label": "License terms"}],"checked_at":"2026-09-30","comparison_basis":"Free accounts pay 15%; paid plans pay 0% platform commission. Lab, tax, shipping and processor costs remain separate.","fee_percent":null,"fee_basis":null,"sort_order":13,"card":{"tag": "Photography galleries", "note": "Lab, shipping, tax, and card costs apply on every plan.", "take": {"label": "Free plan", "value": "15%", "percent": 15, "fact_key": "fact-2"}, "lines": [{"label": "Paid plans", "value": "From $8 a month", "fact_key": "fact-3"}, {"label": "Payments", "value": "Stripe or PayPal", "fact_key": "fact-5"}, {"label": "Free storage", "value": "3 GB", "fact_key": "fact-3"}], "owner": "Pixieset", "groups": [{"label": "Pixieset", "rates": [{"label": "Free plan", "value": "15%", "percent": 15, "fact_key": "fact-2"}, {"label": "Paid plans", "value": "0%", "percent": 0, "fact_key": "fact-2"}]}], "second": {"label": "Paid plans", "value": "0%", "percent": 0, "fact_key": "fact-2"}}}, {"id":"photos-and-stock-images--shutterstock","section_id":"photos-and-stock-images","name":"Shutterstock","summary":"Stock licenses with creator rates based on yearly download levels.","website_url":"https://submit.shutterstock.com/","icon_path":"/platform-fees/icons/submit-shutterstock-com.png","facts":[{"key": "fact-1", "state": "verified", "value": "Contributors earn a percentage of the price Shutterstock receives for each licensed download.", "checked_at": "2026-09-30", "source_url": "https://submit.shutterstock.com/help/en/articles/10594604-how-much-will-i-be-paid-as-a-contributor-to-shutterstock"}, {"key": "fact-2", "state": "verified", "value": "Images and videos each have six separate levels from 15% to 40%; levels advance independently by download count and reset to level 1 every January 1.", "checked_at": "2026-09-30", "source_url": "https://submit.shutterstock.com/help/en/articles/10594604-how-much-will-i-be-paid-as-a-contributor-to-shutterstock"}, {"key": "fact-3", "state": "verified", "value": "Opening a contributor account and submitting work are free.", "checked_at": "2026-09-30", "source_url": "https://submit.shutterstock.com/help/en/articles/12136044-how-do-i-register-for-a-shutterstock-contributor-account"}, {"key": "fact-4", "state": "verified", "value": "Contributor agreement is non-exclusive; creators keep copyright and may license the same work elsewhere.", "checked_at": "2026-09-30", "source_url": "https://submit.shutterstock.com/help/en/articles/12136338-what-is-shutterstock-s-content-exclusivity-policy"}, {"key": "fact-5", "state": "variable", "value": "Automatic monthly payouts use the account setting, but the payout help does not state its floor. Terms v9 sets $35 for electronic or $500 for checks; some countries also wait 90 days from first approval. The official pages conflict on the minimum.", "checked_at": "2026-09-30", "source_url": "https://submit.shutterstock.com/help/en/articles/10617435-how-do-i-get-paid-for-my-work"}],"sources":[{"url": "https://submit.shutterstock.com/help/en/articles/10594604-how-much-will-i-be-paid-as-a-contributor-to-shutterstock", "label": "Royalty levels"}, {"url": "https://submit.shutterstock.com/help/en/articles/12136044-how-do-i-register-for-a-shutterstock-contributor-account", "label": "Account and submission"}, {"url": "https://submit.shutterstock.com/help/en/articles/10617435-how-do-i-get-paid-for-my-work", "label": "Payouts"}, {"url": "https://submit.shutterstock.com/help/en/articles/12136338-what-is-shutterstock-s-content-exclusivity-policy", "label": "Non-exclusive terms"}, {"url": "https://submit.shutterstock.com/help/en/articles/10594678-submitter-terms-of-service-version-9", "label": "Terms v9 minimums"}, {"url": "https://submit.shutterstock.com/help/en/articles/10594583-why-is-my-account-in-a-90-day-waiting-period", "label": "90-day wait"}],"checked_at":"2026-09-30","comparison_basis":"Royalty is a share of Shutterstock’s received license price; six levels reset each January.","fee_percent":null,"fee_basis":null,"sort_order":1,"card":{"tag": "Stock photos and video", "note": "Your level rises with downloads and resets on 1 January. Its pages give different payout minimums.", "take": {"label": "By yearly downloads", "value": "60–85%", "percent": null, "fact_key": "fact-2"}, "lines": [{"label": "Start", "value": "Free", "fact_key": "fact-3"}, {"label": "Exclusive", "value": "No", "fact_key": "fact-4"}, {"label": "Levels", "value": "Reset each January", "fact_key": "fact-2"}], "owner": "Shutterstock", "groups": [{"label": "Six levels", "rates": [{"note": "You keep 15%", "label": "Level 1", "value": "85%", "percent": 85, "fact_key": "fact-2"}, {"note": "You keep 40%", "label": "Level 6", "value": "60%", "percent": 60, "fact_key": "fact-2"}]}]}}, {"id":"photos-and-stock-images--smugmug","section_id":"photos-and-stock-images","name":"SmugMug","summary":"Sell print products and downloads from a photography storefront.","website_url":"https://www.smugmug.com/","icon_path":"/platform-fees/icons/www-smugmug-com.ico","facts":[{"key": "fact-1", "state": "verified", "value": "Portfolio and Pro plans support print and digital-download sales with SmugMug fulfillment.", "checked_at": "2026-09-30", "source_url": "https://www.smugmug.com/plans"}, {"key": "fact-2", "state": "verified", "value": "You keep 85% of your markup above SmugMug print or download base costs; it is not 85% of the full order.", "checked_at": "2026-09-30", "source_url": "https://www.smugmughelp.com/hc/en-us/articles/18212462590868-Get-paid-my-profits"}, {"key": "fact-3", "state": "verified", "value": "Portfolio, the first sales plan, is $282 per year ($23.50 per month billed annually).", "checked_at": "2026-09-30", "source_url": "https://www.smugmug.com/plans"}, {"key": "fact-4", "state": "verified", "value": "SmugMug facilitates seller-chosen licenses under a non-exclusive service license; no seller exclusivity program is stated in its terms.", "checked_at": "2026-09-30", "source_url": "https://www.smugmug.com/about/terms"}, {"key": "fact-5", "state": "variable", "value": "Paid monthly after the 7th: automatic payout at $500 unpaid profit, or request at $5 US / $10 international. US payout is ACH; international is PayPal.", "checked_at": "2026-09-30", "source_url": "https://www.smugmughelp.com/hc/en-us/articles/18212462590868-Get-paid-my-profits"}],"sources":[{"url": "https://www.smugmug.com/plans", "label": "Plan pricing"}, {"url": "https://www.smugmughelp.com/hc/en-us/articles/18212462590868-Get-paid-my-profits", "label": "Profit and payouts"}, {"url": "https://www.smugmug.com/about/terms", "label": "License terms"}],"checked_at":"2026-09-30","comparison_basis":"US sellers, USD, new seller plans; regional exceptions shown on the card.","fee_percent":null,"fee_basis":null,"sort_order":10,"card":{"tag": "Photography storefront", "note": "SmugMug takes 15% of your profit above its print costs, not of the full order.", "take": {"label": "Of your markup", "value": "15%", "percent": 15, "fact_key": "fact-2"}, "lines": [{"label": "Plan", "value": "$282 a year", "fact_key": "fact-3"}, {"label": "Payouts", "value": "Monthly", "fact_key": "fact-5"}, {"label": "Exclusive", "value": "No", "fact_key": "fact-4"}], "owner": "SmugMug", "groups": [{"label": "SmugMug", "rates": [{"note": "You keep 85% above base costs", "label": "Of your markup", "value": "15%", "percent": 15, "fact_key": "fact-2"}]}]}}, {"id":"photos-and-stock-images--stocksy","section_id":"photos-and-stock-images","name":"Stocksy","summary":"Cooperative stock licensing with royalties and possible surplus distributions.","website_url":"https://www.stocksy.com/service/contributor/","icon_path":"/platform-fees/icons/www-stocksy-com.png","facts":[{"key": "fact-1", "state": "verified", "value": "Creators earn stock-license royalties; cooperative patronage returns may also be paid when the co-op has a surplus.", "checked_at": "2026-09-30", "source_url": "https://support.stocksy.com/hc/en-us/articles/201832863-How-much-do-Stocksy-contributors-get-paid"}, {"key": "fact-2", "state": "verified", "value": "Creators receive 50% for standard licenses and 75% for extended licenses and market freezes.", "checked_at": "2026-09-30", "source_url": "https://support.stocksy.com/hc/en-us/articles/201832863-How-much-do-Stocksy-contributors-get-paid"}, {"key": "fact-3", "state": "verified", "value": "Joining requires a one-time $1 USD cooperative share, deducted from the first sale.", "checked_at": "2026-09-30", "source_url": "https://support.stocksy.com/hc/en-us/articles/36923424043412-Does-it-cost-anything-to-join-Stocksy-as-a-contributor"}, {"key": "fact-4", "state": "verified", "value": "Submitted photos/videos and work from the same series are exclusive to Stocksy; members may still work with other agencies and sell personal portfolio, social and print/product uses.", "checked_at": "2026-09-30", "source_url": "https://support.stocksy.com/hc/en-us/articles/201812397-Do-I-have-to-work-exclusively-with-Stocksy"}, {"key": "fact-5", "state": "variable", "value": "Monthly payment on the first Canadian business day once balance reaches $100; Payoneer, PayPal or Wise bank deposit. Regional methods vary and wire transfers may incur an administration fee.", "checked_at": "2026-09-30", "source_url": "https://support.stocksy.com/hc/en-us/articles/360050706452-When-will-I-get-paid"}],"sources":[{"url": "https://support.stocksy.com/hc/en-us/articles/201832863-How-much-do-Stocksy-contributors-get-paid", "label": "Royalties and co-op"}, {"url": "https://support.stocksy.com/hc/en-us/articles/36923424043412-Does-it-cost-anything-to-join-Stocksy-as-a-contributor", "label": "Membership share"}, {"url": "https://support.stocksy.com/hc/en-us/articles/201812397-Do-I-have-to-work-exclusively-with-Stocksy", "label": "Exclusivity"}, {"url": "https://support.stocksy.com/hc/en-us/articles/360050706452-When-will-I-get-paid", "label": "Payout threshold"}, {"url": "https://support.stocksy.com/hc/en-us/articles/360050706312-What-are-Stocksy-s-contributor-payment-options", "label": "Payout methods"}, {"url": "https://www.stocksy.com/legal?id=12", "label": "Supply agreement"}],"checked_at":"2026-09-30","comparison_basis":"Creator share varies by license; the cooperative may also distribute patronage when it has a surplus.","fee_percent":null,"fee_basis":null,"sort_order":7,"card":{"tag": "Artist-owned stock co-op", "note": "Stocksy is a co-op. Members can also get a share of any yearly surplus.", "take": {"label": "Standard licenses", "value": "50%", "percent": 50, "fact_key": "fact-2"}, "lines": [{"label": "Join", "value": "$1 co-op share", "fact_key": "fact-3"}, {"label": "Exclusive", "value": "Yes, for Stocksy work", "fact_key": "fact-4"}, {"label": "Minimum payout", "value": "$100", "fact_key": "fact-5"}], "owner": "Stocksy", "groups": [{"label": "Stocksy", "rates": [{"note": "You keep 50%", "label": "Standard licenses", "value": "50%", "percent": 50, "fact_key": "fact-2"}, {"note": "You keep 75%", "label": "Extended licenses", "value": "25%", "percent": 25, "fact_key": "fact-2"}]}], "second": {"label": "Extended licenses", "value": "25%", "percent": 25, "fact_key": "fact-2"}}}, {"id":"photos-and-stock-images--zenfolio","section_id":"photos-and-stock-images","name":"Zenfolio","summary":"Sell prints and downloads from client galleries and your own site.","website_url":"https://zenfolio.com/","icon_path":"/platform-fees/icons/zenfolio-com.png","facts":[{"key": "fact-1", "state": "verified", "value": "Professional and Advanced plans sell prints and digital downloads from galleries and websites.", "checked_at": "2026-09-30", "source_url": "https://zenfolio.com/plans-pricing/"}, {"key": "fact-2", "state": "verified", "value": "7% commerce fee on the order subtotal before tax/shipping. Digital delivery adds $0.09 per file or $0.99 per gallery download. US processing: Stripe 2.9% + $0.30 or PayPal 3.49% + $0.49; regional rates vary.", "checked_at": "2026-09-30", "source_url": "https://zenfolio.com/plans-pricing/"}, {"key": "fact-3", "state": "verified", "value": "Professional annual: $11.50/month for the first year; renews at standard rates. Monthly billing is $23/month.", "checked_at": "2026-09-30", "source_url": "https://zenfolio.com/plans-pricing/"}, {"key": "fact-4", "state": "verified", "value": "Photographers retain content rights and grant Zenfolio a non-exclusive license to provide its service.", "checked_at": "2026-09-30", "source_url": "https://zenfolio.com/termsofuse/"}, {"key": "fact-5", "state": "variable", "value": "Order profits go to the linked Stripe or PayPal account within 3–5 business days after shipment; route and timing can vary by provider and location.", "checked_at": "2026-09-30", "source_url": "https://success.zenfolio.com/hc/en-us/articles/7430815244947-Managing-Your-Payouts"}],"sources":[{"url": "https://zenfolio.com/plans-pricing/", "label": "Plans, fees, and rates"}, {"url": "https://success.zenfolio.com/hc/en-us/articles/7430771091987-Selling-Overview", "label": "Product costs"}, {"url": "https://success.zenfolio.com/hc/en-us/articles/7430815244947-Managing-Your-Payouts", "label": "Payouts"}, {"url": "https://zenfolio.com/termsofuse/", "label": "Rights and terms"}],"checked_at":"2026-09-30","comparison_basis":"US seller, USD. Professional is required to sell. The $11.50/month annual Professional price is a first-year offer through Sep 30, 2026; annual plans renew at standard rates. Monthly billing is $23/month. Sales add a 7% commerce fee and processing/digital-delivery charges.","fee_percent":7,"fee_basis":"Order subtotal before tax and shipping","sort_order":11,"card":{"tag": "Photography galleries", "note": "The Professional plan is $11.50 a month for the first year when billed yearly.", "take": {"label": "Order subtotal", "value": "7%", "percent": 7, "fact_key": "fact-2"}, "lines": [{"label": "Plan", "value": "$23 a month", "fact_key": "fact-3"}, {"label": "Card fees", "value": "2.9% + 30¢ Stripe", "fact_key": "fact-2"}, {"label": "Downloads", "value": "9¢ per file", "fact_key": "fact-2"}], "owner": "Zenfolio", "groups": [{"label": "Zenfolio", "rates": [{"note": "Before tax and shipping", "label": "Order subtotal", "value": "7%", "percent": 7, "fact_key": "fact-2"}]}]}}, {"id":"podcast-subscriptions-and-monetization--acast","section_id":"podcast-subscriptions-and-monetization","name":"Acast","summary":"Podcast hosting with ads and sponsorship tools.","website_url":"https://www.acast.com/","icon_path":"/platform-fees/icons/www-acast-com.png","facts":[{"key": "fact-1", "state": "verified", "value": "Ads and sponsorships; paid premium subscriptions are also supported.", "checked_at": "2026-09-30", "source_url": "https://www.acast.com/en/pricing"}, {"key": "fact-2", "state": "verified", "value": "Starter is free; Essential is $25/mo or $14.99/mo billed yearly.", "checked_at": "2026-09-30", "source_url": "https://www.acast.com/en/pricing"}, {"key": "fact-3", "state": "verified", "value": "Standard creator terms: Acast receives 50% of net ad revenue; advanced splits are set in a separate term sheet.", "checked_at": "2026-09-30", "source_url": "https://www.acast.com/en/legal/terms-and-conditions-for-creators-standard"}, {"key": "fact-4", "state": "variable", "value": "Acast+ terms dated Oct 2022 list a 15% admin fee plus Stripe processing; current applicability is unconfirmed.", "checked_at": "2026-09-30", "source_url": "https://www.acast.com/terms-and-conditions-acast-plus"}, {"key": "fact-5", "state": "verified", "value": "Public RSS distribution; premium offers use the Acast+ service or designated paywall partners.", "checked_at": "2026-09-30", "source_url": "https://www.acast.com/en/legal/terms-and-conditions-for-creators-advanced"}],"sources":[{"url": "https://www.acast.com/en/pricing", "label": "Plans and prices"}, {"url": "https://www.acast.com/en/legal/terms-and-conditions-for-creators-standard", "label": "Standard revenue split"}, {"url": "https://www.acast.com/en/legal/terms-and-conditions-for-creators-advanced", "label": "Advanced terms"}, {"url": "https://www.acast.com/terms-and-conditions-acast-plus", "label": "Acast+ listener terms"}, {"url": "https://www.acast.com/terms-and-conditions-acast-plus", "label": "Acast+ fees"}],"checked_at":"2026-09-30","comparison_basis":"US creator plans, USD. Standard creator terms give Acast 50% of net ad revenue. Advanced deals use separate term sheets; current Advanced terms may add a variable CPM for HLS. Acast+ terms dated October 2022 list a 15% admin fee plus Stripe processing; current applicability is unconfirmed.","fee_percent":null,"fee_basis":null,"sort_order":4,"card":{"tag": "Podcast hosting and ads", "note": "Advanced creators can agree different splits.", "take": {"label": "Ad revenue", "value": "50%", "percent": 50, "fact_key": "fact-3"}, "lines": [{"label": "Starter", "value": "Free", "fact_key": "fact-2"}, {"label": "Essential", "value": "$14.99 a month, yearly", "fact_key": "fact-2"}, {"label": "Acast+", "value": "Stripe fees extra", "fact_key": "fact-4"}], "owner": "Acast", "groups": [{"label": "Acast", "rates": [{"note": "Of net ad revenue", "label": "Ad revenue", "value": "50%", "percent": 50, "fact_key": "fact-3"}]}, {"label": "Acast+ terms, 2022", "rates": [{"note": "Admin fee, plus Stripe", "label": "Acast+ subscriptions", "value": "15%", "percent": null, "fact_key": "fact-4"}]}], "second": {"label": "Acast+ subscriptions", "value": "15%", "percent": null, "fact_key": "fact-4"}}}, {"id":"podcast-subscriptions-and-monetization--apple-podcasts-subscriptions","section_id":"podcast-subscriptions-and-monetization","name":"Apple Podcasts Subscriptions","summary":"Premium podcast subscriptions sold within Apple Podcasts.","website_url":"https://podcasters.apple.com/878-subscriptions","icon_path":"/platform-fees/icons/podcasters-apple-com.png","facts":[{"key": "fact-1", "state": "verified", "value": "Creators sell monthly or annual paid subscriptions; other podcast revenue, including ads, remains theirs.", "checked_at": "2026-09-30", "source_url": "https://podcasters.apple.com/support/5553-subscription-launch-checklist"}, {"key": "fact-2", "state": "verified", "value": "Apple Podcasters Program costs $19.99/year in the US; the fee varies by country.", "checked_at": "2026-09-30", "source_url": "https://podcasters.apple.com/support/904-availability-of-apple-podcasts-features"}, {"key": "fact-3", "state": "verified", "value": "Apple retains 30% during a subscriber’s first paid year, then 15% after one year of paid service.", "checked_at": "2026-09-30", "source_url": "https://podcasters.apple.com/support/5553-subscription-launch-checklist"}, {"key": "fact-4", "state": "verified", "value": "Applicable taxes are deducted from creator proceeds.", "checked_at": "2026-09-30", "source_url": "https://podcasters.apple.com/support/5553-subscription-launch-checklist"}, {"key": "fact-5", "state": "verified", "value": "Listeners subscribe and access paid shows in Apple Podcasts.", "checked_at": "2026-09-30", "source_url": "https://podcasters.apple.com/support/5553-subscription-launch-checklist"}],"sources":[{"url": "https://podcasters.apple.com/support/5553-subscription-launch-checklist", "label": "Proceeds and options"}, {"url": "https://podcasters.apple.com/support/904-availability-of-apple-podcasts-features", "label": "Availability and fees"}, {"url": "https://podcasters.apple.com/support/974-payments-and-financial-reports", "label": "Payment schedule"}, {"url": "https://podcasters.apple.com/support/5311-understanding-subscription-analytics", "label": "Revenue shares"}],"checked_at":"2026-09-30","comparison_basis":"US Apple Podcasters Program fee shown; annual program fee and subscription availability vary by country.","fee_percent":null,"fee_basis":null,"sort_order":0,"card":{"tag": "Podcast subscriptions", "note": "Listeners subscribe inside Apple Podcasts.", "take": {"label": "First paid year", "value": "30%", "percent": 30, "fact_key": "fact-3"}, "lines": [{"label": "Program", "value": "$19.99 a year", "fact_key": "fact-2"}, {"label": "Ads", "value": "Yours to keep", "fact_key": "fact-1"}, {"label": "Taxes", "value": "Taken from proceeds", "fact_key": "fact-4"}], "owner": "Apple", "groups": [{"label": "Apple", "rates": [{"label": "First paid year", "value": "30%", "percent": 30, "fact_key": "fact-3"}, {"label": "After one paid year", "value": "15%", "percent": 15, "fact_key": "fact-3"}]}], "second": {"label": "After one paid year", "value": "15%", "percent": 15, "fact_key": "fact-3"}}}, {"id":"podcast-subscriptions-and-monetization--buzzsprout","section_id":"podcast-subscriptions-and-monetization","name":"Buzzsprout","summary":"Host a podcast and earn from listener support, subscriptions, and ads.","website_url":"https://www.buzzsprout.com/","icon_path":"/platform-fees/icons/www-buzzsprout-com.png","facts":[{"key": "fact-1", "state": "verified", "value": "Listener support, paid subscriptions, and Buzzsprout Ads", "checked_at": "2026-09-30", "source_url": "https://www.buzzsprout.com/subscriptions"}, {"key": "fact-2", "state": "verified", "value": "Free plan: 2 upload hours/month, episodes hosted 90 days. Audio plan: $15/month billed annually, 72 hours/year.", "checked_at": "2026-09-30", "source_url": "https://www.buzzsprout.com/pricing"}, {"key": "fact-3", "state": "verified", "value": "Listener subscriptions use an 85/15 revenue split; the current public FAQ does not say whether processing is included.", "checked_at": "2026-09-30", "source_url": "https://www.buzzsprout.com/help/184-faq-podcasters"}, {"key": "fact-4", "state": "not_public", "value": "Buzzsprout Ads eligibility and creator share depend on enrollment terms; no standard ad share is published in the public terms.", "checked_at": "2026-09-30", "source_url": "https://www.buzzsprout.com/tos"}, {"key": "fact-5", "state": "verified", "value": "Premium episodes appear in the public feed; earnings go to Buzzsprout Wallet for PayPal cash-out.", "checked_at": "2026-09-30", "source_url": "https://www.buzzsprout.com/subscriptions"}],"sources":[{"url": "https://www.buzzsprout.com/subscriptions", "label": "Subscriptions and fee"}, {"url": "https://www.buzzsprout.com/pricing", "label": "Hosting plans"}, {"url": "https://www.buzzsprout.com/tos", "label": "Ads terms"}, {"url": "https://www.buzzsprout.com/help/184-faq-podcasters", "label": "Subscription FAQ"}],"checked_at":"2026-09-30","comparison_basis":"Listener subscriptions use an 85/15 split; Buzzsprout Ads shares depend on enrollment and are not public. USD plan example.","fee_percent":15,"fee_basis":"Listener subscription revenue; processor treatment is not stated.","sort_order":6,"card":{"tag": "Podcast hosting", "note": "Buzzsprout does not say whether card fees are inside the 15%.", "take": {"label": "Listener subscriptions", "value": "15%", "percent": 15, "fact_key": "fact-3"}, "lines": [{"label": "Audio plan", "value": "$15 a month, yearly", "fact_key": "fact-2"}, {"label": "Free plan", "value": "2 hours a month", "fact_key": "fact-2"}, {"label": "Cash out", "value": "PayPal", "fact_key": "fact-5"}], "owner": "Buzzsprout", "groups": [{"label": "Buzzsprout", "rates": [{"note": "You keep 85%", "label": "Listener subscriptions", "value": "15%", "percent": 15, "fact_key": "fact-3"}]}]}}, {"id":"podcast-subscriptions-and-monetization--captivate","section_id":"podcast-subscriptions-and-monetization","name":"Captivate","summary":"Host podcasts with download-based plans.","website_url":"https://www.captivate.fm/","icon_path":"/platform-fees/icons/www-captivate-fm.ico","facts":[{"key": "fact-1", "state": "verified", "value": "Podcast ads, paid memberships, and listener tips", "checked_at": "2026-09-30", "source_url": "https://help.captivate.fm/en/article/monetization-faqs-lddbc8/"}, {"key": "fact-2", "state": "verified", "value": "Personal: $17/month billed yearly or $19/month; 30,000 downloads/month; 30-day free trial.", "checked_at": "2026-09-30", "source_url": "https://www.captivate.fm/pricing"}, {"key": "fact-3", "state": "verified", "value": "Captivate fee: 12% on memberships, 5% on tips, and none on advertising revenue.", "checked_at": "2026-09-30", "source_url": "https://help.captivate.fm/en/article/fees-for-memberships-and-tips-17prkry/"}, {"key": "fact-4", "state": "verified", "value": "Stripe processing: 2.9% + $0.30 per transaction; withdrawal: 0.25% + $0.30. Captivate takes no withdrawal fee.", "checked_at": "2026-09-30", "source_url": "https://help.captivate.fm/en/article/fees-for-memberships-and-tips-17prkry/"}, {"key": "fact-5", "state": "verified", "value": "All plans include private podcasting, unlimited podcasts, and unlimited storage.", "checked_at": "2026-09-30", "source_url": "https://www.captivate.fm/pricing"}],"sources":[{"url": "https://www.captivate.fm/pricing", "label": "Plans and limits"}, {"url": "https://help.captivate.fm/en/article/fees-for-memberships-and-tips-17prkry/", "label": "Membership and tip fees"}, {"url": "https://help.captivate.fm/en/article/monetization-faqs-lddbc8/", "label": "Ads terms"}, {"url": "https://help.captivate.fm/en/article/how-to-check-campaign-and-programmatic-earnings-12prqs8/", "label": "Ad payouts"}],"checked_at":"2026-09-30","comparison_basis":"US-dollar Personal plan; platform rates differ for memberships, tips, and ads. Stripe and payout processing are separate.","fee_percent":null,"fee_basis":null,"sort_order":8,"card":{"tag": "Podcast hosting", "note": "Stripe withdrawals cost 0.25% + 30¢. Captivate adds no withdrawal fee.", "take": {"label": "Memberships", "value": "12%", "percent": 12, "fact_key": "fact-3"}, "lines": [{"label": "Personal", "value": "$17 a month, yearly", "fact_key": "fact-2"}, {"label": "Card fees", "value": "2.9% + 30¢ Stripe", "fact_key": "fact-4"}, {"label": "Ads", "value": "No Captivate fee", "fact_key": "fact-3"}], "owner": "Captivate", "groups": [{"label": "Captivate", "rates": [{"label": "Memberships", "value": "12%", "percent": 12, "fact_key": "fact-3"}, {"label": "Tips", "value": "5%", "percent": 5, "fact_key": "fact-3"}, {"label": "Ads", "value": "0%", "percent": 0, "fact_key": "fact-3"}]}], "second": {"label": "Tips", "value": "5%", "percent": 5, "fact_key": "fact-3"}}}, {"id":"podcast-subscriptions-and-monetization--castos","section_id":"podcast-subscriptions-and-monetization","name":"Castos","summary":"Host public and private podcasts.","website_url":"https://castos.com/","icon_path":"/platform-fees/icons/castos-com.png","facts":[{"key": "fact-1", "state": "verified", "value": "Castos Ads, paid podcast subscriptions, and listener donations", "checked_at": "2026-09-30", "source_url": "https://castos.com/advertising/"}, {"key": "fact-2", "state": "verified", "value": "Essentials: $19/month or $190/year; includes up to 100 private subscribers.", "checked_at": "2026-09-30", "source_url": "https://castos.com/pricing/"}, {"key": "fact-3", "state": "verified", "value": "Commerce subscriptions and donations have 0% Castos fee. Castos Ads pays per listen but does not publish a payout percentage.", "checked_at": "2026-09-30", "source_url": "https://castos.com/podcast-monetization-platforms/"}, {"key": "fact-4", "state": "verified", "value": "Stripe processing is 2.9% + $0.30 per payment; exceeding a plan’s private-subscriber limit raises the plan tier.", "checked_at": "2026-09-30", "source_url": "https://castos.com/offer-paid-podcast-subscriptions-with-stripe/"}, {"key": "fact-5", "state": "verified", "value": "Private delivery uses RSS or the Castos app. Ads pay by PayPal at $10 minimum, 45 days after month-end.", "checked_at": "2026-09-30", "source_url": "https://support.castos.com/article/303-castos-ads-faq"}],"sources":[{"url": "https://castos.com/pricing/", "label": "Plans and limits"}, {"url": "https://support.castos.com/article/144-plans-and-pricing-faq", "label": "Prices and overages"}, {"url": "https://castos.com/commerce/", "label": "Commerce fees"}, {"url": "https://castos.com/offer-paid-podcast-subscriptions-with-stripe/", "label": "Subscriptions and Stripe"}, {"url": "https://castos.com/listener-donations/", "label": "Donation fees"}, {"url": "https://castos.com/advertising/", "label": "Castos Ads"}, {"url": "https://support.castos.com/article/303-castos-ads-faq", "label": "Ads payouts"}, {"url": "https://castos.com/podcast-monetization-platforms/", "label": "Fee comparison"}],"checked_at":"2026-09-30","comparison_basis":"US-dollar Essentials plan; Castos takes no commerce share, while ad revenue terms are not public. Processing is separate.","fee_percent":0,"fee_basis":"Commerce subscriptions and donations; excludes Castos Ads","sort_order":13,"card":{"tag": "Podcast hosting", "note": "Castos Ads pays per listen, but its share is not published.", "take": {"label": "Subscriptions and donations", "value": "0%", "percent": 0, "fact_key": "fact-3"}, "lines": [{"label": "Essentials", "value": "$19 a month", "fact_key": "fact-2"}, {"label": "Card fees", "value": "2.9% + 30¢ Stripe", "fact_key": "fact-4"}, {"label": "Private subs", "value": "100 on Essentials", "fact_key": "fact-2"}], "owner": "Castos", "groups": [{"label": "Castos", "rates": [{"label": "Subscriptions and donations", "value": "0%", "percent": 0, "fact_key": "fact-3"}]}]}}, {"id":"podcast-subscriptions-and-monetization--hello-audio","section_id":"podcast-subscriptions-and-monetization","name":"Hello Audio","summary":"Deliver private audio feeds.","website_url":"https://helloaudio.fm/","icon_path":"/platform-fees/icons/helloaudio-fm.png","facts":[{"key": "fact-1", "state": "verified", "value": "Paid private podcast feeds for courses, memberships, and exclusive audio", "checked_at": "2026-09-30", "source_url": "https://helloaudio.fm/pricing/"}, {"key": "fact-2", "state": "verified", "value": "Starter: $17/month or $14/month billed annually; 1 private feed, unlimited listeners.", "checked_at": "2026-09-30", "source_url": "https://helloaudio.fm/pricing/"}, {"key": "fact-3", "state": "verified", "value": "Hello Audio fee varies by plan: Starter 5%, Pro 2%, Powerhouse 0%.", "checked_at": "2026-09-30", "source_url": "https://help.helloaudio.fm/en/articles/10260550-using-the-signup-page-to-add-listeners"}, {"key": "fact-4", "state": "verified", "value": "Stripe processing: 2.9% + $0.30 per transaction.", "checked_at": "2026-09-30", "source_url": "https://help.helloaudio.fm/en/articles/10260550-using-the-signup-page-to-add-listeners"}, {"key": "fact-5", "state": "verified", "value": "Private feeds play in podcast apps that accept an imported feed URL; Starter includes 1 private and 1 public feed.", "checked_at": "2026-09-30", "source_url": "https://helloaudio.fm/pricing/"}],"sources":[{"url": "https://helloaudio.fm/pricing/", "label": "Plans and feeds"}, {"url": "https://help.helloaudio.fm/en/articles/10260550-using-the-signup-page-to-add-listeners", "label": "Payment and fees"}, {"url": "https://helloaudio.fm/hello-audio-signup-page/", "label": "Signup and payments"}],"checked_at":"2026-09-30","comparison_basis":"US-dollar private-feed hosting; platform share depends on plan, with Stripe processing charged separately.","fee_percent":null,"fee_basis":null,"sort_order":12,"card":{"tag": "Private audio feeds", "note": "Listeners import your private feed into their podcast app.", "take": {"label": "Starter", "value": "5%", "percent": 5, "fact_key": "fact-3"}, "lines": [{"label": "Starter", "value": "$14 a month, yearly", "fact_key": "fact-2"}, {"label": "Card fees", "value": "2.9% + 30¢ Stripe", "fact_key": "fact-4"}, {"label": "Listeners", "value": "Unlimited", "fact_key": "fact-2"}], "owner": "Hello Audio", "groups": [{"label": "Hello Audio", "rates": [{"label": "Starter", "value": "5%", "percent": 5, "fact_key": "fact-3"}, {"label": "Pro", "value": "2%", "percent": 2, "fact_key": "fact-3"}, {"label": "Powerhouse", "value": "0%", "percent": 0, "fact_key": "fact-3"}]}], "second": {"label": "Powerhouse", "value": "0%", "percent": 0, "fact_key": "fact-3"}}}, {"id":"podcast-subscriptions-and-monetization--libsyn","section_id":"podcast-subscriptions-and-monetization","name":"Libsyn","summary":"Host audio and video podcasts with monetization options.","website_url":"https://libsyn.com/","icon_path":"/platform-fees/icons/libsyn-com.png","facts":[{"key": "fact-1", "state": "verified", "value": "Automatic Podcast Ads, Libsyn Ads, PodRoll, and Apple Podcasts Subscriptions", "checked_at": "2026-09-30", "source_url": "https://libsyn.com/plans-and-pricing/"}, {"key": "fact-2", "state": "verified", "value": "Basic: $12/month after a 30-day free trial; 3 audio upload hours/month.", "checked_at": "2026-09-30", "source_url": "https://libsyn.com/plans-and-pricing/"}, {"key": "fact-3", "state": "verified", "value": "Automatic Ads pay creators 50% below 50,000 monthly downloads and 60% at 50,000 or more (equivalent Libsyn shares: 50% and 40%). Libsyn Ads Marketplace standard commission is 30%, negotiable. Apple subscription commission is 30% in year one and 15% after a subscriber has paid for one year.", "checked_at": "2026-09-30", "source_url": "https://libsyn.com/automatic-podcast-ads/"}, {"key": "fact-4", "state": "variable", "value": "Apple Podcasts Subscriptions require an Apple Podcasters Program membership; US annual fee is $19.99 and varies by country.", "checked_at": "2026-09-30", "source_url": "https://podcasters.apple.com/support/904-availability-of-apple-podcasts-features"}, {"key": "fact-5", "state": "verified", "value": "Distributes to Apple Podcasts, Spotify, YouTube, and 20+ platforms; supports private and subscriber audio.", "checked_at": "2026-09-30", "source_url": "https://libsyn.com/plans-and-pricing/"}],"sources":[{"url": "https://libsyn.com/plans-and-pricing/", "label": "Plans"}, {"url": "https://libsyn.com/automatic-podcast-ads/", "label": "Automatic Ads"}, {"url": "https://advertising.libsyn.com/terms", "label": "Ads Marketplace"}, {"url": "https://libsyn.com/blog/apple-podcasts-subscriptions-earn-money-with-your-podcast/", "label": "Apple setup"}, {"url": "https://podcasters.apple.com/support/5311-understanding-subscription-analytics", "label": "Apple proceeds"}, {"url": "https://podcasters.apple.com/support/904-availability-of-apple-podcasts-features", "label": "Apple program fee"}],"checked_at":"2026-09-30","comparison_basis":"US-dollar hosting plans; monetization cuts differ by automatic ads, marketplace ads, and Apple subscription tenure.","fee_percent":null,"fee_basis":null,"sort_order":7,"card":{"tag": "Podcast hosting", "note": "Apple subscriptions need an Apple Podcasters Program membership.", "take": {"label": "Automatic ads, under 50K", "value": "50%", "percent": 50, "fact_key": "fact-3"}, "lines": [{"label": "Basic", "value": "$12 a month", "fact_key": "fact-2"}, {"label": "Apple program", "value": "$19.99 a year", "fact_key": "fact-4"}, {"label": "Uploads", "value": "3 hours a month", "fact_key": "fact-2"}], "owner": "Libsyn", "groups": [{"label": "Automatic ads", "rates": [{"note": "Monthly downloads", "label": "Automatic ads, under 50K", "value": "50%", "percent": 50, "fact_key": "fact-3"}, {"label": "Automatic ads, 50K+", "value": "40%", "percent": 40, "fact_key": "fact-3"}]}, {"label": "Other", "rates": [{"note": "Can be negotiated", "label": "Libsyn Ads Marketplace", "value": "30%", "percent": 30, "fact_key": "fact-3"}, {"label": "Apple subscriptions, year 1", "value": "30%", "percent": 30, "fact_key": "fact-3"}, {"label": "Apple, after year 1", "value": "15%", "percent": 15, "fact_key": "fact-3"}]}], "second": {"label": "Automatic ads, 50K+", "value": "40%", "percent": 40, "fact_key": "fact-3"}}}, {"id":"podcast-subscriptions-and-monetization--podbean","section_id":"podcast-subscriptions-and-monetization","name":"Podbean","summary":"Podcast hosting with monetization and private podcast options.","website_url":"https://www.podbean.com/","icon_path":"/platform-fees/icons/www-podbean-com.ico","facts":[{"key": "fact-1", "state": "verified", "value": "Ads Marketplace, PodAds, Podbean Premium sales and Apple Podcasts Subscriptions integration.", "checked_at": "2026-09-30", "source_url": "https://www.podbean.com/how-to-monetize-a-podcast"}, {"key": "fact-2", "state": "verified", "value": "Unlimited Audio is $12/mo billed annually or $17 monthly; Unlimited Plus is $29/$39 for audio and video.", "checked_at": "2026-09-30", "source_url": "https://www.podbean.com/podcast-hosting-pricing"}, {"key": "fact-3", "state": "verified", "value": "Paid hosts receive 70% of net Ads Marketplace revenue (Podbean retains 30%); free-plan hosts receive no ad share. PodAds costs $1 per 1,000 ad downloads served.", "checked_at": "2026-09-30", "source_url": "https://www.podbean.com/podbean-podcaster-monetize-terms"}, {"key": "fact-4", "state": "verified", "value": "Ad share is calculated after taxes, card/other processing, bad debt, chargebacks, commissions, credits, refunds, and advertiser discounts.", "checked_at": "2026-09-30", "source_url": "https://www.podbean.com/podbean-podcaster-monetize-terms"}, {"key": "fact-5", "state": "verified", "value": "Ads Marketplace and PodAds require U.S.-person status; public shows use RSS, while Premium delivery uses Podbean apps/web or Apple access.", "checked_at": "2026-09-30", "source_url": "https://www.podbean.com/podbean-podcaster-monetize-terms"}],"sources":[{"url": "https://www.podbean.com/podcast-hosting-pricing", "label": "Hosting plans"}, {"url": "https://www.podbean.com/podbean-podcaster-monetize-terms", "label": "Ads terms, 2026"}, {"url": "https://help.podbean.com/support/solutions/articles/25000035194-how-does-podbean-ads-marketplace-work", "label": "Eligibility and split"}, {"url": "https://www.podbean.com/premium", "label": "Premium content"}, {"url": "https://www.podbean.com/how-to-monetize-a-podcast", "label": "Monetization options"}, {"url": "https://www.podbean.com/podbean-podcaster-monetize-terms", "label": "Eligibility and fees"}],"checked_at":"2026-09-30","comparison_basis":"U.S. persons only for Ads Marketplace and PodAds; the 30% ad share applies to eligible paid-plan hosts, calculated on net revenue.","fee_percent":null,"fee_basis":null,"sort_order":5,"card":{"tag": "Podcast hosting", "note": "Free-plan hosts get no ad share.", "take": {"label": "Ads Marketplace", "value": "30%", "percent": 30, "fact_key": "fact-3"}, "lines": [{"label": "Unlimited Audio", "value": "$12 a month, yearly", "fact_key": "fact-2"}, {"label": "PodAds", "value": "$1 per 1,000 ads", "fact_key": "fact-3"}, {"label": "Access", "value": "US only", "fact_key": "fact-5"}], "owner": "Podbean", "groups": [{"label": "Podbean", "rates": [{"note": "You keep 70% of net; paid plans only", "label": "Ads Marketplace", "value": "30%", "percent": 30, "fact_key": "fact-3"}]}]}}, {"id":"podcast-subscriptions-and-monetization--redcircle","section_id":"podcast-subscriptions-and-monetization","name":"RedCircle","summary":"Podcast hosting with ad insertion and a promotions marketplace.","website_url":"https://redcircle.com/","icon_path":"/platform-fees/icons/redcircle-com.ico","facts":[{"key": "fact-1", "state": "verified", "value": "Host-read and programmatic ads, donations, exclusive subscriptions, and partner premium revenue", "checked_at": "2026-09-30", "source_url": "https://redcircle.com/monetization-terms"}, {"key": "fact-2", "state": "verified", "value": "Growth: $19.99/month or $180/year ($15/month annual equivalent); Core plan is free.", "checked_at": "2026-09-30", "source_url": "https://support.redcircle.com/articles/7581935770-redcircle-account-plans"}, {"key": "fact-3", "state": "verified", "value": "Platform share: 30% host-read ads/sponsorships, 50% programmatic ads, 4.5% donations, 12% exclusive subscriptions, and 50% partner premium revenue. Donation and subscription rates apply after actual facilitation expenses and refunds are deducted; ad rates use net ad revenue.", "checked_at": "2026-09-30", "source_url": "https://redcircle.com/monetization-terms"}, {"key": "fact-4", "state": "verified", "value": "Payment processing and refunds reduce the net donation/subscription amount before the listed share is calculated.", "checked_at": "2026-09-30", "source_url": "https://redcircle.com/monetization-terms"}, {"key": "fact-5", "state": "verified", "value": "Public RSS distribution; exclusive content is delivered to paid subscribers.", "checked_at": "2026-09-30", "source_url": "https://support.redcircle.com/articles/3339748780-exclusive-content"}],"sources":[{"url": "https://redcircle.com/pricing", "label": "Plan comparison"}, {"url": "https://support.redcircle.com/articles/7581935770-redcircle-account-plans", "label": "Plan prices"}, {"url": "https://redcircle.com/monetization-terms", "label": "Revenue shares"}, {"url": "https://support.redcircle.com/articles/3339748780-exclusive-content", "label": "Subscriber access"}],"checked_at":"2026-09-30","comparison_basis":"US-dollar Growth plan; shares differ by ad type, donations, subscriptions, and deductions before the share.","fee_percent":null,"fee_basis":null,"sort_order":10,"card":{"tag": "Podcast hosting and ads", "note": "Ad shares are taken from net ad revenue.", "take": {"label": "Programmatic ads", "value": "50%", "percent": 50, "fact_key": "fact-3"}, "lines": [{"label": "Core plan", "value": "Free", "fact_key": "fact-2"}, {"label": "Growth", "value": "$19.99 a month", "fact_key": "fact-2"}, {"label": "Taken first", "value": "Processing, refunds", "fact_key": "fact-4"}], "owner": "RedCircle", "groups": [{"label": "Ads", "rates": [{"label": "Host-read ads", "value": "30%", "percent": 30, "fact_key": "fact-3"}, {"label": "Programmatic ads", "value": "50%", "percent": 50, "fact_key": "fact-3"}]}, {"label": "Listener payments", "rates": [{"note": "After costs and refunds", "label": "Donations", "value": "4.5%", "percent": 4.5, "fact_key": "fact-3"}, {"note": "After costs and refunds", "label": "Exclusive subscriptions", "value": "12%", "percent": 12, "fact_key": "fact-3"}, {"label": "Partner premium revenue", "value": "50%", "percent": 50, "fact_key": "fact-3"}]}], "second": {"label": "Donations", "value": "4.5%", "percent": 4.5, "fact_key": "fact-3"}}}, {"id":"podcast-subscriptions-and-monetization--spotify-for-creators","section_id":"podcast-subscriptions-and-monetization","name":"Spotify for Creators","summary":"Host podcasts with eligible subscription monetization.","website_url":"https://creators.spotify.com/","icon_path":"/platform-fees/icons/creators-spotify-com.ico","facts":[{"key": "fact-1", "state": "verified", "value": "Subscriptions; eligible shows may also earn ad and premium-video revenue through the Partner Program.", "checked_at": "2026-09-30", "source_url": "https://creators.spotify.com/features/monetization"}, {"key": "fact-2", "state": "verified", "value": "Spotify for Creators podcast hosting is free.", "checked_at": "2026-09-30", "source_url": "https://creators.spotify.com/features/podcast"}, {"key": "fact-3", "state": "verified", "value": "No platform fee on legacy direct subscriptions through October 19; from October 20 new Memberships pay 10% of net earnings. Migrated legacy subscriptions keep old fees until cancellation.", "checked_at": "2026-09-30", "source_url": "https://support.spotify.com/us/creators/article/fee-schedule-and-cashing-out/"}, {"key": "fact-4", "state": "verified", "value": "Through October 19: 5.5% processing plus 0.8–1.6% FX when currencies differ. From October 20, new Memberships’ 10% includes processing, FX, and payout; migrated subscriptions keep old fees until cancellation. US payout: rolling 30 days after 30-day onboarding, $10 minimum.", "checked_at": "2026-09-30", "source_url": "https://support.spotify.com/us/creators/article/fee-schedule-and-cashing-out/"}, {"key": "fact-5", "state": "verified", "value": "Subscriptions require 2 episodes and 100 unique Spotify listeners in 60 days in supported markets. Partner Program has separate eligibility: 1,000 audience, 2,000 listening hours in 30 days, and 3 episodes.", "checked_at": "2026-09-30", "source_url": "https://creators.spotify.com/features/monetization"}],"sources":[{"url": "https://support.spotify.com/us/creators/article/fee-schedule-and-cashing-out/", "label": "Fee schedules"}, {"url": "https://creators.spotify.com/features/monetization", "label": "Models and eligibility"}, {"url": "https://creators.spotify.com/features/podcast", "label": "Hosting"}],"checked_at":"2026-09-30","comparison_basis":"Direct podcast subscriptions; US fee schedule. Availability and payout currency vary by market.","fee_percent":null,"fee_basis":null,"sort_order":1,"card":{"tag": "Podcast hosting", "note": "From 20 October, new Memberships pay 10%, which covers processing and payouts.", "take": {"label": "Legacy subscriptions", "value": "0%", "percent": 0, "fact_key": "fact-3"}, "lines": [{"label": "Hosting", "value": "Free", "fact_key": "fact-2"}, {"label": "Legacy fees", "value": "5.5% processing", "fact_key": "fact-4"}, {"label": "Subscriptions", "value": "Need 100 listeners", "fact_key": "fact-5"}], "owner": "Spotify", "groups": [{"label": "Spotify", "rates": [{"note": "Plus processing, until 19 Oct", "label": "Legacy subscriptions", "value": "0%", "percent": 0, "fact_key": "fact-3"}, {"note": "From 20 Oct; processing included", "label": "New Memberships", "value": "10%", "percent": 10, "fact_key": "fact-3"}]}], "second": {"label": "New Memberships", "value": "10%", "percent": 10, "fact_key": "fact-3"}}}, {"id":"podcast-subscriptions-and-monetization--spreaker","section_id":"podcast-subscriptions-and-monetization","name":"Spreaker","summary":"Publish podcasts and offer subscriptions to supporters.","website_url":"https://www.spreaker.com/","icon_path":"/platform-fees/icons/www-spreaker-com.ico","facts":[{"key": "fact-1", "state": "verified", "value": "Ad Exchange advertising and recurring Supporters Club memberships", "checked_at": "2026-09-30", "source_url": "https://www.spreaker.com/plans"}, {"key": "fact-2", "state": "verified", "value": "Free Speech: $0; Broadcaster: $20/month; higher plans cost $50 and $250/month.", "checked_at": "2026-09-30", "source_url": "https://www.spreaker.com/plans"}, {"key": "fact-3", "state": "verified", "value": "Ad Exchange creators get 60% of ad CPM; Spreaker playback adds up to 10 points. Supporters Club fee: 20% on Free, 0% on paid plans.", "checked_at": "2026-09-30", "source_url": "https://help.spreaker.com/en/articles/3753298-spreaker-monetization-the-ad-exchange"}, {"key": "fact-4", "state": "variable", "value": "Web Supporters Club payments use Stripe: 5% + $0.25 per payment; fees can vary by payment method, card, and country.", "checked_at": "2026-09-30", "source_url": "https://help.spreaker.com/en/articles/8659184-supporters-club-payment-fees"}, {"key": "fact-5", "state": "variable", "value": "Ads: PayPal, $10 minimum; paid within 60 days after month-end. Supporters Club payout timing is not stated.", "checked_at": "2026-09-30", "source_url": "https://help.spreaker.com/en/articles/3753298-spreaker-monetization-the-ad-exchange"}],"sources":[{"url": "https://www.spreaker.com/plans", "label": "Plans and Club fees"}, {"url": "https://help.spreaker.com/en/articles/3892734-what-about-impressions-cpm-and-revenue", "label": "Ad Exchange shares"}, {"url": "https://help.spreaker.com/en/articles/3753298-spreaker-monetization-the-ad-exchange", "label": "Ad payouts"}, {"url": "https://help.spreaker.com/en/articles/8659184-supporters-club-payment-fees", "label": "Club processing fees"}, {"url": "https://www.spreaker.com/terms/pricing", "label": "Membership payouts"}, {"url": "https://help.spreaker.com/en/articles/8193474-on-platform-revenue-boost", "label": "Ad revenue boost"}, {"url": "https://help.spreaker.com/en/articles/8886498-how-to-activate-the-supporters-club", "label": "Club activation"}],"checked_at":"2026-09-30","comparison_basis":"US-dollar plan examples; ad share depends on playback, while Supporters Club fees depend on the plan.","fee_percent":null,"fee_basis":null,"sort_order":11,"card":{"tag": "Podcast hosting", "note": "Ad earnings are paid by PayPal within 60 days after the month ends.", "take": {"label": "Ad Exchange", "value": "40%", "percent": 40, "fact_key": "fact-3"}, "lines": [{"label": "Broadcaster", "value": "$20 a month", "fact_key": "fact-2"}, {"label": "Club card fee", "value": "5% + 25¢", "fact_key": "fact-4"}, {"label": "Ad payouts", "value": "$10 minimum", "fact_key": "fact-5"}], "owner": "Spreaker", "groups": [{"label": "Ads", "rates": [{"note": "You keep 60%", "label": "Ad Exchange", "value": "40%", "percent": 40, "fact_key": "fact-3"}, {"note": "You keep up to 70%", "label": "Plays on Spreaker", "value": "30%", "percent": 30, "fact_key": "fact-3"}]}, {"label": "Supporters Club", "rates": [{"label": "Supporters Club, Free", "value": "20%", "percent": 20, "fact_key": "fact-3"}, {"label": "Paid plans", "value": "0%", "percent": 0, "fact_key": "fact-3"}]}], "second": {"label": "Supporters Club, Free", "value": "20%", "percent": 20, "fact_key": "fact-3"}}}, {"id":"podcast-subscriptions-and-monetization--supercast","section_id":"podcast-subscriptions-and-monetization","name":"Supercast","summary":"Sell private podcast subscriptions.","website_url":"https://www.supercast.com/","icon_path":"/platform-fees/icons/www-supercast-com.png","facts":[{"key": "fact-1", "state": "verified", "value": "Paid memberships with hosted private podcast feeds.", "checked_at": "2026-09-30", "source_url": "https://www.supercast.com/pricing"}, {"key": "fact-2", "state": "verified", "value": "$0.59 per subscriber per month, plus Stripe fees.", "checked_at": "2026-09-30", "source_url": "https://www.supercast.com/pricing"}, {"key": "fact-3", "state": "verified", "value": "Subscriptions: no percentage platform fee. One-time payments: 15%, capped at $1.50.", "checked_at": "2026-09-30", "source_url": "https://www.supercast.com/pricing"}, {"key": "fact-4", "state": "verified", "value": "Stripe: 2.9% + $0.30 per transaction, plus 0.7% per recurring payment (USD).", "checked_at": "2026-09-30", "source_url": "https://www.supercast.com/pricing"}, {"key": "fact-5", "state": "verified", "value": "Listeners use private podcast feeds in supported podcast apps.", "checked_at": "2026-09-30", "source_url": "https://www.supercast.com/pricing"}],"sources":[{"url": "https://www.supercast.com/pricing", "label": "Subscription and one-time fees"}],"checked_at":"2026-09-30","comparison_basis":"USD; subscription prices set by creator, with Supercast and Stripe fees deducted from listener payments.","fee_percent":null,"fee_basis":null,"sort_order":2,"card":{"tag": "Private podcast subscriptions", "note": "Supercast charges 59¢ per subscriber each month instead of a percentage.", "take": {"label": "Memberships", "value": "0%", "percent": 0, "fact_key": "fact-3"}, "lines": [{"label": "Per subscriber", "value": "59¢ a month", "fact_key": "fact-2"}, {"label": "Card fees", "value": "2.9% + 30¢ Stripe", "fact_key": "fact-4"}, {"label": "Stripe Billing", "value": "+ 0.7%", "fact_key": "fact-4"}], "owner": "Supercast", "groups": [{"label": "Supercast", "rates": [{"label": "Memberships", "value": "0%", "percent": 0, "fact_key": "fact-3"}, {"note": "Max $1.50", "label": "One-time payments", "value": "15%", "percent": 15, "fact_key": "fact-3"}]}], "second": {"label": "One-time payments", "value": "15%", "percent": 15, "fact_key": "fact-3"}}}, {"id":"podcast-subscriptions-and-monetization--supporting-cast","section_id":"podcast-subscriptions-and-monetization","name":"Sup