UPDATE directory_registry_seed SET is_published=false,published_at=NULL,updated_at=NULL;
DO $registry_guard$
BEGIN
 IF (SELECT count(*) FROM directory_registry_seed) <> 65 THEN
  RAISE EXCEPTION 'Unexpected platform directory registry export count';
 END IF;
 IF EXISTS (
  SELECT 1 FROM public.stack127_pages current JOIN directory_registry_seed seed USING(slug)
  WHERE (to_jsonb(current)-ARRAY['id','is_published','published_at','updated_at','row_updated_at'])
     IS DISTINCT FROM (to_jsonb(seed)-ARRAY['id','is_published','published_at','updated_at','row_updated_at'])
 ) THEN
  RAISE EXCEPTION 'Directory registry metadata changed since the reviewed development export';
 END IF;
END;
$registry_guard$;
INSERT INTO public.stack127_pages ("slug", "meta_title", "meta_description", "is_published", "created_at", "published_at", "updated_at", "cover_image_url", "page_type", "sitemap_priority", "label", "page_family", "row_created_at", "row_updated_at")
 SELECT "slug", "meta_title", "meta_description", "is_published", "created_at", "published_at", "updated_at", "cover_image_url", "page_type", "sitemap_priority", "label", "page_family", "row_created_at", "row_updated_at" FROM directory_registry_seed
ON CONFLICT (slug) DO UPDATE SET
 "meta_title"=EXCLUDED."meta_title",
 "meta_description"=EXCLUDED."meta_description",
 "is_published"=EXCLUDED."is_published",
 "published_at"=EXCLUDED."published_at",
 "updated_at"=EXCLUDED."updated_at",
 "cover_image_url"=EXCLUDED."cover_image_url",
 "page_type"=EXCLUDED."page_type",
 "sitemap_priority"=EXCLUDED."sitemap_priority",
 "label"=EXCLUDED."label",
 "page_family"=EXCLUDED."page_family";
DO $publication_readback$
BEGIN
 IF EXISTS (SELECT 1 FROM public.stack127_pages WHERE (slug='platform-fees' OR slug LIKE 'platform-fees/%') AND (is_published OR published_at IS NOT NULL)) THEN
  RAISE EXCEPTION 'Directory registry seed must remain unpublished';
 END IF;
 IF EXISTS (
  (SELECT slug,id,is_published,published_at,updated_at FROM public.stack127_pages WHERE is_published AND NOT (slug='platform-fees' OR slug LIKE 'platform-fees/%')
   EXCEPT SELECT slug,id,is_published,published_at,updated_at FROM directory_public_routes_before)
  UNION ALL
  (SELECT slug,id,is_published,published_at,updated_at FROM directory_public_routes_before
   EXCEPT SELECT slug,id,is_published,published_at,updated_at FROM public.stack127_pages WHERE is_published AND NOT (slug='platform-fees' OR slug LIKE 'platform-fees/%'))
 ) THEN
  RAISE EXCEPTION 'An unrelated published route changed';
 END IF;
END;
$publication_readback$;
